function hccErfc(x){
  const E=HCC_ERF, y=Math.abs(x);
  if(y<=0.46875){ const z=y>1.11e-16?y*y:0; let xn=E.a[4]*z, xd=z;
    for(let i=0;i<3;i++){ xn=(xn+E.a[i])*z; xd=(xd+E.b[i])*z; }
    return 1-x*(xn+E.a[3])/(xd+E.b[3]); }
  let r;
  if(y<=4.0){ let xn=E.c[8]*y, xd=y;
    for(let i=0;i<7;i++){ xn=(xn+E.c[i])*y; xd=(xd+E.d[i])*y; }
    r=(xn+E.c[7])/(xd+E.d[7]); }
  else { const z=1/(y*y); let xn=E.p[5]*z, xd=z;
    for(let i=0;i<4;i++){ xn=(xn+E.p[i])*z; xd=(xd+E.q[i])*z; }
    r=z*(xn+E.p[4])/(xd+E.q[4]); r=(E.sqrpi-r)/y; }
  /* the split exponential keeps the tail accurate where exp(-y²) would underflow
     the mantissa away before the rational factor could use it */
  const ys=Math.floor(y*16)/16, del=(y-ys)*(y+ys);
  r=Math.exp(-ys*ys)*Math.exp(-del)*r;
  return x<0?2-r:r;
}

const hccPhi=x=>0.5*hccErfc(-x/Math.SQRT2);

function hccInvPhi(p){
  if(!(p>0&&p<1)) return NaN;
  const A=[-3.969683028665376e+01,2.209460984245205e+02,-2.759285104469687e+02,
           1.383577518672690e+02,-3.066479806614716e+01,2.506628277459239e+00],
        B=[-5.447609879822406e+01,1.615858368580409e+02,-1.556989798598866e+02,
           6.680131188771972e+01,-1.328068155288572e+01],
        C=[-7.784894002430293e-03,-3.223964580411365e-01,-2.400758277161838e+00,
           -2.549732539343734e+00,4.374664141464968e+00,2.938163982698783e+00],
        D=[7.784695709041462e-03,3.224671290700398e-01,2.445134137142996e+00,3.754408661907416e+00];
  const lo=0.02425; let x, q;
  if(p<lo){ q=Math.sqrt(-2*Math.log(p));
    x=(((((C[0]*q+C[1])*q+C[2])*q+C[3])*q+C[4])*q+C[5])/((((D[0]*q+D[1])*q+D[2])*q+D[3])*q+1); }
  else if(p<=1-lo){ q=p-0.5; const r=q*q;
    x=(((((A[0]*r+A[1])*r+A[2])*r+A[3])*r+A[4])*r+A[5])*q/(((((B[0]*r+B[1])*r+B[2])*r+B[3])*r+B[4])*r+1); }
  else { q=Math.sqrt(-2*Math.log(1-p));
    x=-(((((C[0]*q+C[1])*q+C[2])*q+C[3])*q+C[4])*q+C[5])/((((D[0]*q+D[1])*q+D[2])*q+D[3])*q+1); }
  for(let i=0;i<3;i++){ const e=hccPhi(x)-p, u=e*Math.sqrt(2*Math.PI)*Math.exp(x*x/2);
    x=x-u/(1+x*u/2); }
  return x;
}

function hccTruncQuantile(mu,sig,p,upper){
  const mass=hccPhi((upper-mu)/sig);
  if(!(mass>0)) return null;
  return mu+sig*hccInvPhi(p*mass);
}

function hccSimpsonLog(f,aLo,aHi,n){
  let m=n|0; if(m%2) m++;
  const s0=Math.log(aLo), s1=Math.log(aHi), h=(s1-s0)/m;
  let s=f(Math.exp(s0))+f(Math.exp(s1));
  for(let i=1;i<m;i++) s+=f(Math.exp(s0+i*h))*(i%2?4:2);
  return s*h/3;
}

function hccS3Reconstruct(opt){
  const O=Object.assign({}, HCC_S3R, opt||{});
  const {c,G,kB,hbar,Mpc}=HCC_S3C, Gly=HCC_S3_GLY;
  const H0=O.H0_km*1000/Mpc, h=O.H0_km/100;
  /* the hard sign condition, and how much of the published posterior survives it */
  const pClosed=hccPhi((0-O.mu_k)/O.sig_k);
  const quant={}; for(const p of O.probes) quant[p]=hccTruncQuantile(O.mu_k,O.sig_k,p,0);
  const Ok=quant[0.5];
  /* a profile-like one-sided bound, which does not depend on the prior the way a
     quantile does: where does Δχ² reach 2.71 below the constrained Ω_K = 0⁻ ? */
  const OkProf=O.mu_k-Math.sqrt(O.mu_k*O.mu_k+O.deltaChi2*O.sig_k*O.sig_k);
  const RcOf=x=>c/(H0*Math.sqrt(Math.abs(x)));
  const Rc=RcOf(Ok), RcGly=Rc/Gly;
  const V=2*Math.PI*Math.PI*Rc*Rc*Rc, K=1/(Rc*Rc);
  const rhoC=3*H0*H0/(8*Math.PI*G), rhoPhys=rhoC*(1-Ok);
  /* radiation bookkeeping: photons plus the massless-equivalent relativistic
     sector. The paper is explicit that the fixed 0.06 eV neutrino sector makes
     this convention-dependent at the 10⁻⁵–10⁻⁴ level, so it is labelled
     "effective" wherever it is shown rather than quietly called Ω_r */
  const aRad=Math.PI*Math.PI*Math.pow(kB,4)/(15*Math.pow(hbar,3)*c*c*c);
  const uGamma=aRad*Math.pow(O.T_cmb,4), OmGamma=(uGamma/(c*c))/rhoC;
  const OmR=OmGamma*(1+(7/8)*Math.pow(4/11,4/3)*O.N_eff);
  const OmB=O.omega_b/(h*h), OmX=1-Ok-O.Omega_m-OmR;
  /* the closed-Λ background, which is a MODEL and is labelled one everywhere */
  const Ea=a=>Math.sqrt(OmR*Math.pow(a,-4)+O.Omega_m*Math.pow(a,-3)+Ok*Math.pow(a,-2)+OmX);
  const secGyr=365.25*24*3600*1e9;
  const age=hccSimpsonLog(a=>1/Ea(a),O.aMin,1,O.quadN)/H0/secGyr;
  const chiP=hccSimpsonLog(a=>1/(a*Ea(a)),O.aMin,1,O.quadN);
  const chiE=hccSimpsonLog(a=>1/(a*Ea(a)),1,O.aMax,O.quadN);
  const Dp=(c/H0)*chiP, De=(c/H0)*chiE, chi=Dp/Rc;
  const fObs=(chi-Math.sin(chi)*Math.cos(chi))/Math.PI;
  const shells=O.probes.map(p=>({p, Ok:quant[p], RcGly:RcOf(quant[p])/Gly,
    V_m3:2*Math.PI*Math.PI*Math.pow(RcOf(quant[p]),3)}));
  return {
    inputs:O, H0, pClosed, quantiles:quant, shells,
    Ok, OkProf, RcProfGly:RcOf(OkProf)/Gly,
    Rc, RcGly, V, K, R3:6*K, rhoC, rhoPhys,
    OmGamma, OmR, OmB, OmX, uGamma,
    Lambda:3*H0*H0*OmX/(c*c),
    age, chiP, chiE, Dp, De, DpGly:Dp/Gly, DeGly:De/Gly, chi, fObs,
    k1_Mpc:Math.sqrt(3)/Rc*Mpc, lambda1_Mpc:2*Math.PI*Rc/Math.sqrt(3)/Mpc,
    /* the globalization theorem, ready to be handed any mean density at all */
    globalize:qbar=>2*Math.PI*Math.PI*Rc*Rc*Rc*qbar
  };
}

