const volMeasure = chi => chi - Math.sin(chi)*Math.cos(chi);

const S3kernel   = chi => { const m = volMeasure(chi); return m>1e-12 ? 2*Math.sin(chi)**2/m : 3/Math.max(chi,1e-9); };

