const MERC_A        = 5.790905e10;

const MERC_E        = 0.20563069;

const MERC_PERIOD_D = 87.9691;

const CYC_ARCSEC_PER_RAD = 206264.80625;

const cycPerihelionShift=(aM,e)=>6*Math.PI*MERC_GM_SUN/(aM*MERC_C*MERC_C*(1-e*e));

const cycPerihelionArcsecPerCentury=(aM,e,periodDays)=>cycPerihelionShift(aM,e)*CYC_ARCSEC_PER_RAD*(36525/periodDays);

const cycPerihelionPeriodYears=(aM,e,periodDays)=>(2*Math.PI/cycPerihelionShift(aM,e))*periodDays/365.2425;

const CYC_EARTH_A = 1.495979e11;

const CYC_EARTH_E = 0.016708;

const CYC_EARTH_P = 365.25636;

const cycRelativisticShare=()=>{ const grEarth=cycPerihelionPeriodYears(CYC_EARTH_A,CYC_EARTH_E,CYC_EARTH_P); return {grEarthYears:grEarth, observedEarthYears:CYC_APSIDAL_Y, ratio:grEarth/CYC_APSIDAL_Y, sharePercent:100*CYC_APSIDAL_Y/grEarth}; };

const cycBeat=(p,q)=>{ const d=1/p-1/q; return (Math.abs(d)<1e-30)?Infinity:1/Math.abs(d); };

const cycPrecessionFromYears=()=>cycBeat(CYC_TROPICAL_Y,CYC_SIDEREAL_Y)/365.2425;

const cycClimaticPrecession=()=>1/(1/cycPrecessionFromYears()+1/CYC_APSIDAL_Y);

function cycTripleCommensurability(pA,pB,pC,maxA){
  const NA=maxA||400;
  let best=null;
  for(let n=1;n<=NA;n++){
    const t=n*pA;
    const nB=Math.round(t/pB), nC=Math.round(t/pC);
    if(nB<1||nC<1) continue;
    const eB=Math.abs(t-nB*pB), eC=Math.abs(t-nC*pC);
    const worst=Math.max(eB,eC);
    if(!best||worst<best.worstDays) best={nA:n,nB,nC,days:t,errB:t-nB*pB,errC:t-nC*pC,worstDays:worst};
  }
  if(best) best.ppm=best.worstDays/best.days*1e6;
  return best;
}

const cycLongitudeShiftDeg=periodDays=>((periodDays%1)+1)%1*360;

const CYC_NODE_REGRESSION = 6798.383;

const cycNodalYear=()=>1/(1/CYC_TROPICAL_Y+1/CYC_NODE_REGRESSION);

const CYC_NODAL_Y = 346.620076;

const cycNutationYears=()=>CYC_NODE_REGRESSION/365.2425;

const cycSarosSolarRoute=()=>19*cycNodalYear();

const cycSarosRouteRatio=()=>{
  const lunar=223*CYC_SYNODIC, solar=cycSarosSolarRoute();
  const lunarMiss=Math.abs(lunar-242*CYC_DRACONIC), solarMiss=Math.abs(solar-lunar);
  return {lunar, solar, lunarMiss, solarMiss, ratio:solarMiss/lunarMiss};
};

const CYC_INEX_LUNATIONS = 358;

const CYC_INEX_DRACONIC_HALVES = 777;

const cycInexDays=()=>CYC_INEX_LUNATIONS*CYC_SYNODIC;

function cycEclipseSeries2(periodDays,draconicCount){
  const miss=periodDays-draconicCount*CYC_DRACONIC;
  const driftDeg=miss/CYC_DRACONIC*360;
  const count=Math.round(2*CYC_ECLIPSE_LIMIT_DEG/Math.abs(driftDeg));
  return {periodDays, draconicCount, missDays:miss, driftDeg, count,
          years:count*periodDays/365.2425};
}

const cycSarosSeries2=()=>cycEclipseSeries2(223*CYC_SYNODIC,242);

const cycInexSeries=()=>cycEclipseSeries2(cycInexDays(),CYC_INEX_DRACONIC_HALVES/2);

