const wotArcs=id=>{
  if(id==='yuga') return WOT_YUGA_YR.map(y=>y/WOT_MAHAYUGA_YR);
  if(id==='jain'){ const half=WOT_JAIN_ARA.reduce((a,b)=>a+b,0);
    /* the wheel is BOTH halves: avasarpiṇī descending then utsarpiṇī ascending, the
       second the first reversed — which is why it is a wheel and not a ladder */
    return [...WOT_JAIN_ARA,...[...WOT_JAIN_ARA].reverse()].map(x=>x/(2*half)); }
  const T=WOT_TRADITIONS.find(t=>t.id===id); const n=(T&&T.div)||1;
  return new Array(n).fill(1/n);
};

const wotSharedProportion=()=>{
  const jain=WOT_JAIN_ARA.slice(0,4), yuga=WOT_YUGA_YR.map(y=>y/WOT_YUGA_YR[3]);
  const j=jain.map(x=>x/jain[3]);
  return {jain:j, yuga, identical:j.every((x,i)=>Math.abs(x-yuga[i])<1e-9)};
};

