function cycSarosSeries(){
  const t=cycTripleCommensurability(CYC_SYNODIC,CYC_DRACONIC,CYC_ANOMALISTIC,400);
  const nodeDriftDeg=(t.errB/CYC_DRACONIC)*360;
  const count=Math.round(2*CYC_ECLIPSE_LIMIT_DEG/Math.abs(nodeDriftDeg));
  return {saros:t, nodeDriftDeg, count, years:count*t.days/365.2425,
          longitudeShiftDeg:cycLongitudeShiftDeg(t.days),
          exeligmosShiftDeg:cycLongitudeShiftDeg(3*t.days)};
}

