const CMB_T_EMIT=()=>HCC_S3R.T_cmb*(1+CMB_CAMB.meta.derived.zstar);

const CMB_COLOR_RANGE_MUK=300;

function cmbD(l,which){ const A=CMB_CAMB.spec[which||'TT']; return l>=0&&l<A.length?A[l]:0; }

function cmbPlanckColor(dT){ const x=Math.max(0,Math.min(255,(dT+CMB_COLOR_RANGE_MUK)/(2*CMB_COLOR_RANGE_MUK)*255)), i=Math.min(254,Math.floor(x)), f=x-i, A=CMB_PLANCK_CMAP[i], B=CMB_PLANCK_CMAP[i+1];
  return [0,1,2].map(k=>(A[k]+(B[k]-A[k])*f)/255); }

function cmbAcoustic(){ const th=CMB_CAMB.meta.derived.thetastar/100, lA=Math.PI/th; return {thetaStarDeg:th*180/Math.PI, lA, peaks:CMB_CAMB.meta.peaksTT.map((l,n)=>({n:n+1, l, D:cmbD(l), phase:n+1-l/lA}))}; }

function cmbSigmaT(fwhmArcmin){ const s=fwhmArcmin/60*Math.PI/180/Math.sqrt(8*Math.log(2)); let v=0;
  for(let l=2;l<CMB_CAMB.spec.TT.length;l++){ const Cl=2*Math.PI*cmbD(l)/(l*(l+1)); v+=(2*l+1)*Cl*Math.exp(-l*(l+1)*s*s); } return Math.sqrt(v/(4*Math.PI)); }

function cmbCIE(lam){ const g=(x,m,s1,s2)=>{ const t=(x-m)/(x<m?s1:s2); return Math.exp(-0.5*t*t); };
  return [1.056*g(lam,599.8,37.9,31.0)+0.362*g(lam,442.0,16.0,26.7)-0.065*g(lam,501.1,20.4,26.2),
          0.821*g(lam,568.8,46.9,40.5)+0.286*g(lam,530.9,16.3,31.1),
          1.217*g(lam,437.0,11.8,36.0)+0.681*g(lam,459.0,26.0,13.8)]; }

function cmbPlanckianXYZ(T){ const h=6.62607015e-34, c=299792458, k=1.380649e-23; let X=0,Y=0,Z=0;
  for(let lam=360;lam<=830;lam+=1){ const m=lam*1e-9, B=1/(Math.pow(m,5)*(Math.exp(h*c/(m*k*T))-1)), f=cmbCIE(lam); X+=B*f[0]; Y+=B*f[1]; Z+=B*f[2]; }
  const S=X+Y+Z; return {x:X/S, y:Y/S, X:X/Y, Y:1, Z:Z/Y}; }

function cmbPlanckianRGB(T){ const q=cmbPlanckianXYZ(T), lin=[3.2406*q.X-1.5372*q.Y-0.4986*q.Z, -0.9689*q.X+1.8758*q.Y+0.0415*q.Z, 0.0557*q.X-0.2040*q.Y+1.0570*q.Z].map(v=>Math.max(0,v)),
    m=Math.max(...lin), enc=v=>{ v/=m; return v<=0.0031308?12.92*v:1.055*Math.pow(v,1/2.4)-0.055; }; return lin.map(enc); }

const CT_COSMO=(()=>{ const h=HCC_S3R.H0_km/100, Or=2.4728e-5*Math.pow(HCC_S3R.T_cmb/2.7255,4)*(1+0.2271*HCC_S3R.N_eff)/(h*h);
  return Object.freeze({h, Om:HCC_S3R.Omega_m, Or, OL:1-HCC_S3R.Omega_m-Or, tH:977.7922216807891/HCC_S3R.H0_km, cH:299792.458/HCC_S3R.H0_km*3.2615637771674333e-3}); })();

const ctE=z=>{ const C=CT_COSMO, a=1+z; return Math.sqrt(C.Or*a*a*a*a+C.Om*a*a*a+C.OL); };

let CT_TABLE=null;

function ctTable(){ if(CT_TABLE) return CT_TABLE; const C=CT_COSMO, n=4000, lmax=Math.log(1+1e6), zs=new Float64Array(n+1), chi=new Float64Array(n+1), age=new Float64Array(n+1);
  for(let i=0;i<=n;i++) zs[i]=Math.expm1(i/n*lmax);
  for(let i=1;i<=n;i++){ const z0=zs[i-1], z1=zs[i], f=z=>1/ctE(z); chi[i]=chi[i-1]+0.5*(f(z0)+f(z1))*(z1-z0); }
  /* the age: t(z) = ∫_z^∞ dz'/((1+z')H); from the top down, with the radiation-era tail t(z_max) = 1/(2H₀√Ω_r (1+z)²) */
  const g=z=>1/((1+z)*ctE(z)); age[n]=1/(2*Math.sqrt(C.Or)*Math.pow(1+zs[n],2));
  for(let i=n-1;i>=0;i--) age[i]=age[i+1]+0.5*(g(zs[i])+g(zs[i+1]))*(zs[i+1]-zs[i]);
  for(let i=0;i<=n;i++){ chi[i]*=C.cH; age[i]*=C.tH; }
  CT_TABLE={zs, chi, age, n}; return CT_TABLE; }

function ctInterp(xs,ys,x){ const n=xs.length-1; if(x<=xs[0]) return ys[0]; if(x>=xs[n]) return ys[n]; let lo=0, hi=n; while(hi-lo>1){ const m=(lo+hi)>>1; if(xs[m]<=x) lo=m; else hi=m; }
  const t=(x-xs[lo])/(xs[hi]-xs[lo]); return ys[lo]+t*(ys[hi]-ys[lo]); }

function ctChiOfZ(z){ const T=ctTable(); return ctInterp(T.zs,T.chi,z); }

function ctZOfChi(chiGly){ const T=ctTable(); return ctInterp(T.chi,T.zs,chiGly); }

function ctAgeOfZ(z){ const T=ctTable(); return ctInterp(T.zs,T.age,z); }

const CT_T0=()=>ctAgeOfZ(0);

function ctSFR(z){ return 0.015*Math.pow(1+z,2.7)/(1+Math.pow((1+z)/2.9,5.6)); }

let HZ_TAB=null;

function hzTable(){ if(HZ_TAB) return HZ_TAB; const C=CT_COSMO, x0=-25, x1=9, n=24000, dx=(x1-x0)/n, X=new Float64Array(n+1), T=new Float64Array(n+1), P=new Float64Array(n+1);
  const E=x=>{ const a=Math.exp(x); return Math.sqrt(C.Or/(a*a*a*a)+C.Om/(a*a*a)+C.OL); }, ft=x=>C.tH/E(x), fp=x=>C.cH/(Math.exp(x)*E(x)), a0=Math.exp(x0);
  X[0]=x0; T[0]=C.tH*a0*a0/(2*Math.sqrt(C.Or)); P[0]=C.cH*a0/Math.sqrt(C.Or);
  for(let i=1;i<=n;i++){ const xa=x0+(i-1)*dx, xb=x0+i*dx, xm=xa+dx/2; X[i]=xb; T[i]=T[i-1]+dx/6*(ft(xa)+4*ft(xm)+ft(xb)); P[i]=P[i-1]+dx/6*(fp(xa)+4*fp(xm)+fp(xb)); }
  HZ_TAB={C, X, T, P, n, Pinf:P[n]+C.cH/(Math.exp(x1)*Math.sqrt(C.OL)), E}; return HZ_TAB; }

function hzAgeAtA(a){ const H=hzTable(), x=Math.log(a), {X,T,n}=H; if(x<=X[0]) return T[0]*Math.exp(2*(x-X[0])); if(x>=X[n]) return T[n]+(x-X[n])*H.C.tH/Math.sqrt(H.C.OL);
  let lo=0, hi=n; while(hi-lo>1){ const m=(lo+hi)>>1; if(X[m]<=x) lo=m; else hi=m; } const f=(x-X[lo])/(X[hi]-X[lo]); return T[lo]+f*(T[hi]-T[lo]); }

function hzAtT(tGyr){ const H=hzTable(), {X,T,P,n,C,Pinf,E}=H; if(!(tGyr>0)) return null; let x, p;
  if(tGyr<=T[0]){ const a=Math.sqrt(2*Math.sqrt(C.Or)*tGyr/C.tH); x=Math.log(a); p=C.cH*a/Math.sqrt(C.Or); }
  else if(tGyr>=T[n]){ x=X[n]+(tGyr-T[n])*Math.sqrt(C.OL)/C.tH; p=Pinf-C.cH/(Math.exp(x)*Math.sqrt(C.OL)); }
  else { let lo=0, hi=n; while(hi-lo>1){ const m=(lo+hi)>>1; if(T[m]<=tGyr) lo=m; else hi=m; } const f=(tGyr-T[lo])/(T[hi]-T[lo]); x=X[lo]+f*(X[hi]-X[lo]); p=P[lo]+f*(P[hi]-P[lo]); }
  const Ex=E(x), a=Math.exp(Math.min(700,x)); return {t:tGyr, lnA:x, a, z:x<0?Math.expm1(-x):null, particle:p, event:Math.max(0,Pinf-p), hubbleComoving:x>700?0:C.cH/(a*Ex), hubbleProper:C.cH/Ex, light:tGyr, limit:Pinf}; }

function hzTimeAtParticle(p){ const H=hzTable(), {X,T,P,n,C,Pinf}=H; if(!(p>0)) return 0;
  if(p<=P[0]){ const a=p*Math.sqrt(C.Or)/C.cH; return C.tH*a*a/(2*Math.sqrt(C.Or)); }
  if(p>=P[n]){ if(p>=Pinf) return Infinity; const a=C.cH/((Pinf-p)*Math.sqrt(C.OL)); return T[n]+(Math.log(a)-X[n])*C.tH/Math.sqrt(C.OL); }
  let lo=0, hi=n; while(hi-lo>1){ const m=(lo+hi)>>1; if(P[m]<=p) lo=m; else hi=m; } const f=(p-P[lo])/(P[hi]-P[lo]); return T[lo]+f*(T[hi]-T[lo]); }

function hzEmissionTime(chiGly,dtYears){ const h=hzAtT(hzAgeAtA(1)+(dtYears||0)/1e9); if(!h) return null; const pE=h.particle-Math.max(0,chiGly); return pE<=0?0:hzTimeAtParticle(pE); }

function hzScreenAt(tGyr,aEv){ const h=hzAtT(tGyr), tEv=hzAgeAtA(aEv); if(!h||tGyr<=tEv) return null; return h.particle-hzAtT(tEv).particle; }

const HZ_EVENTS=Object.freeze({lss:1/1090.9, eq:1/3420.4, accel:1/1.6312});

function hzCausal(chiGly,tGyr){ if(!(chiGly>0)) return null; const H=hzTable(), t=tGyr??hzAgeAtA(1), h=hzAtT(t), P=h?h.particle:0, E=h?h.event:H.Pinf;
  const tp=p=>p>=H.Pinf?Infinity:p<=0?0:hzTimeAtParticle(p);
  return {chi:chiGly, t, firstLight:tp(chiGly), visible:P>=chiGly, seenAt:P>=chiGly?tp(P-chiGly):null,
    sunset:H.Pinf-chiGly>0?tp(H.Pinf-chiGly):0, reachable:E>chiGly, arrival:E>chiGly?tp(P+chiGly):Infinity,
    replyBack:E>2*chiGly?tp(P+2*chiGly):Infinity, lastQuestion:H.Pinf-2*chiGly>0?tp(H.Pinf-2*chiGly):0,
    exchanges:Math.floor(E/(2*chiGly)), dialogue:E/2, event:E, particle:P, Pinf:H.Pinf}; }

const CT_EPOCHS=Object.freeze([
  {id:'plasma', z:[1089.9,1e6], en:'the opaque plasma', ru:'непрозрачная плазма', de:'das undurchsichtige Plasma'},
  {id:'recomb', z:[1089.9,1089.9], en:'recombination — the light we see as the CMB', ru:'рекомбинация — свет, который мы видим как реликт', de:'Rekombination — das Licht des CMB'},
  {id:'dark', z:[20,1089.9], en:'the dark ages', ru:'тёмные века', de:'das dunkle Zeitalter'},
  {id:'dawn', z:[10,20], en:'cosmic dawn — the first stars', ru:'космический рассвет — первые звёзды', de:'kosmische Morgendämmerung'},
  {id:'reion', z:[5.5,10], en:'reionization', ru:'реионизация', de:'Reionisation'},
  {id:'noon', z:[1,5.5], en:'cosmic noon — most stars are born', ru:'космический полдень — рождается большинство звёзд', de:'kosmischer Mittag'},
  {id:'late', z:[0,1], en:'the accelerating, ageing universe', ru:'ускоряющаяся, стареющая Вселенная', de:'das beschleunigte, alternde Universum'}]);

function ctEpochOfZ(z){ return CT_EPOCHS.find(e=>e.id!=='recomb'&&z>=e.z[0]&&z<e.z[1])||CT_EPOCHS[CT_EPOCHS.length-1]; }

function ctColorAtTime(tGyr){ const t0=CT_T0(); const zOfT=t=>{ const T=ctTable(); return ctInterp(Array.from(T.age).reverse(),Array.from(T.zs).reverse(),t); };
  if(tGyr>t0){ const f=1-Math.exp(-(tGyr-t0)/4.5), c0=[1.0,0.68,0.28], c1=[1.0,0.42,0.18], b=(0.3+0.7*ctSFR(0)/ctSFR(1.86))*Math.exp(-(tGyr-t0)/4.5);
    return {rgb:c0.map((v,i)=>v+(c1[i]-v)*f), b:Math.max(0.05,b), z:-1, epoch:'future'}; }
  const z=zOfT(Math.max(1e-9,tGyr));
  if(z>=20){ const T=HCC_S3R.T_cmb*(1+z), rgb=cmbPlanckianRGB(Math.min(Math.max(T,1000),20000)),   /* below ~1000 K the eye sees no colour, only the fading: the hue is held, the brightness falls */ b=z>=1089.9?1:Math.max(0.06,Math.min(1,Math.pow(Math.max(0,(T-600)/2400),1.4)));
    return {rgb, b, z, epoch:ctEpochOfZ(z).id, T}; }
  const K=[[20,[0.62,0.3,1.0]],[10,[0.38,0.4,1.0]],[6,[0.25,0.58,1.0]],[2,[0.4,0.85,1.0]],[0.63,[1.0,0.84,0.42]],[0,[1.0,0.68,0.28]]];
  let i=0; while(i<K.length-2&&z<K[i+1][0]) i++; const [za,ca]=K[i], [zb,cb]=K[i+1], w=Math.max(0,Math.min(1,(za-z)/(za-zb)));
  return {rgb:ca.map((v,k)=>v+(cb[k]-v)*w), b:0.3+0.7*ctSFR(z)/ctSFR(1.86), z, epoch:ctEpochOfZ(z).id}; }

function ctColorAtChi(chiGly,dtYears){ if(Math.abs(dtYears||0)<1e6) dtYears=0; if(!dtYears){ const z=ctZOfChi(Math.max(0,chiGly)); return ctColorAtTime(ctAgeOfZ(z)); } const tE=hzEmissionTime(chiGly,dtYears); return ctColorAtTime(tE==null?0:tE); }

function shtIdx(l,m){ return l*l+l+m; }

function shtGauss(n){ const x=new Float64Array(n), w=new Float64Array(n);
  for(let i=0;i<Math.ceil(n/2);i++){ let z=Math.cos(Math.PI*(i+0.75)/(n+0.5)), pp=0;
    for(let it=0;it<100;it++){ let p1=1, p2=0; for(let j=1;j<=n;j++){ const p3=p2; p2=p1; p1=((2*j-1)*z*p2-(j-1)*p3)/j; } pp=n*(z*p1-p2)/(z*z-1); const dz=p1/pp; z-=dz; if(Math.abs(dz)<1e-15) break; }
    x[i]=z; x[n-1-i]=-z; w[i]=w[n-1-i]=2/((1-z*z)*pp*pp); }
  return {x,w}; }

function shtLambda(L,x,out){ const s=Math.sqrt(Math.max(0,1-x*x)); let pmm=Math.sqrt(1/(4*Math.PI));
  for(let m=0;m<=L;m++){ if(m>0) pmm*=-s*Math.sqrt((2*m+1)/(2*m)); out[shtIdx(m,m)]=pmm; if(m===L) break;
    let p1=pmm, p2=x*Math.sqrt(2*m+3)*pmm; out[shtIdx(m+1,m)]=p2;
    for(let l=m+2;l<=L;l++){ const a=Math.sqrt((4*l*l-1)/(l*l-m*m)), b=Math.sqrt(((l-1)*(l-1)-m*m)/(4*(l-1)*(l-1)-1)), p=a*(x*p2-b*p1); out[shtIdx(l,m)]=p; p1=p2; p2=p; } }
  return out; }

function shtGrid(L,noTable){ const nt=L+1, G=shtGauss(nt); let np=1; while(np<2*L+2) np<<=1; const S=(L+1)*(L+1);
  let lam=null; if(!noTable){ lam=new Float64Array(nt*S); const tmp=new Float64Array(S); for(let j=0;j<nt;j++){ shtLambda(L,G.x[j],tmp); lam.set(tmp,j*S); } }
  return {L, nt, np, x:G.x, w:G.w, lam, tmp:new Float64Array(S)}; }

function shtRing(G,j){ const S=(G.L+1)*(G.L+1); return G.lam?G.lam.subarray(j*S,(j+1)*S):shtLambda(G.L,G.x[j],G.tmp); }

function shtSynth(G,a){ const {L,nt,np}=G, map=new Float64Array(nt*np), re=new Float64Array(np), im=new Float64Array(np);
  for(let j=0;j<nt;j++){ re.fill(0); im.fill(0); const R=shtRing(G,j);
    for(let m=0;m<=L;m++){ let c=0, s=0; for(let l=m;l<=L;l++){ const lam=R[shtIdx(l,m)]; if(m===0) c+=a[shtIdx(l,0)]*lam; else { c+=a[shtIdx(l,m)]*lam*Math.SQRT2; s+=a[shtIdx(l,-m)]*lam*Math.SQRT2; } }
      /* f(φ) = Σ_m c_m cos mφ + s_m sin mφ = Re Σ (c_m − i s_m) e^{imφ} */
      re[m]+=c; im[m]-=s; }
    lssFFT1(re,im,0,1,np,true); for(let k=0;k<np;k++) map[j*np+k]=re[k]; }
  return map; }

function shtAnalysis(G,map,weighted){ const {L,nt,np}=G, a=new Float64Array((L+1)*(L+1)), re=new Float64Array(np), im=new Float64Array(np), wphi=2*Math.PI/np;
  for(let j=0;j<nt;j++){ for(let k=0;k<np;k++){ re[k]=map[j*np+k]; im[k]=0; } lssFFT1(re,im,0,1,np,false);   /* re[m] = Σ f cos mφ, im[m] = −Σ f sin mφ */
    const wj=weighted===false?1:G.w[j]*wphi, R=shtRing(G,j);
    for(let m=0;m<=L;m++){ const c=re[m]*wj, s=-im[m]*wj; for(let l=m;l<=L;l++){ const lam=R[shtIdx(l,m)]; if(m===0) a[shtIdx(l,0)]+=c*lam; else { a[shtIdx(l,m)]+=c*lam*Math.SQRT2; a[shtIdx(l,-m)]+=s*lam*Math.SQRT2; } } } }
  return a; }

function shtPixArea(G){ const A=new Float64Array(G.nt*G.np); for(let j=0;j<G.nt;j++) for(let k=0;k<G.np;k++) A[j*G.np+k]=G.w[j]*2*Math.PI/G.np; return A; }

function shtCl(a,L){ const C=new Float64Array(L+1); for(let l=0;l<=L;l++){ let s=0; for(let m=-l;m<=l;m++) s+=a[shtIdx(l,m)]**2; C[l]=s/(2*l+1); } return C; }

function shtRealize(C,L,seed){ const rnd=mulberry(seed|0), a=new Float64Array((L+1)*(L+1)), g=()=>{ let u=0; while(u===0) u=rnd(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*rnd()); };
  for(let l=0;l<=L;l++){ const s=Math.sqrt(Math.max(0,C[l]||0)); for(let m=-l;m<=l;m++) a[shtIdx(l,m)]=s*g(); } return a; }

function wfMask(G,bDeg,holes){ const M=new Float64Array(G.nt*G.np), sb=Math.sin((bDeg||0)*Math.PI/180);
  for(let j=0;j<G.nt;j++){ const ct=G.x[j], st=Math.sqrt(1-ct*ct); for(let k=0;k<G.np;k++){ const ph=2*Math.PI*k/G.np, n=[st*Math.cos(ph), st*Math.sin(ph), ct]; let ok=Math.abs(ct)>=sb;
      if(ok&&holes) for(const h of holes){ if(n[0]*h.c[0]+n[1]*h.c[1]+n[2]*h.c[2]>Math.cos(h.r*Math.PI/180)){ ok=false; break; } }
      M[j*G.np+k]=ok?1:0; } }
  return M; }

function wienerFilter(G,C,sigma2,mask,d,opt){ opt=opt||{}; const L=G.L, S=(L+1)*(L+1), A=shtPixArea(G), Ninv=new Float64Array(A.length); let fsky=0;
  for(let p=0;p<A.length;p++){ Ninv[p]=mask[p]*A[p]/sigma2; fsky+=mask[p]*A[p]; } fsky/=4*Math.PI;
  const lOf=new Int32Array(S); for(let l=0;l<=L;l++) for(let m=-l;m<=l;m++) lOf[shtIdx(l,m)]=l;
  const Sinv=i=>lOf[i]<2||!(C[lOf[i]]>0)?0:1/C[lOf[i]], live=i=>lOf[i]>=2&&C[lOf[i]]>0;
  const Aop=x=>{ const mp=shtSynth(G,x); for(let p=0;p<mp.length;p++) mp[p]*=Ninv[p]; const y=shtAnalysis(G,mp,false); for(let i=0;i<S;i++) y[i]=live(i)?y[i]+Sinv(i)*x[i]:0; return y; };
  const dn=Float64Array.from(d,(v,p)=>v*Ninv[p]), b=shtAnalysis(G,dn,false); for(let i=0;i<S;i++) if(!live(i)) b[i]=0;
  const Pinv=new Float64Array(S); for(let i=0;i<S;i++) Pinv[i]=live(i)?1/(Sinv(i)+fsky/sigma2):0;
  let x=new Float64Array(S), r=Float64Array.from(b), z=r.map((v,i)=>v*Pinv[i]), p=Float64Array.from(z), rz=0; for(let i=0;i<S;i++) rz+=r[i]*z[i];
  const bn=Math.sqrt(b.reduce((s,v)=>s+v*v,0))||1, hist=[]; let it=0;
  for(;it<(opt.maxIter||400);it++){ const Ap=Aop(p); let pAp=0; for(let i=0;i<S;i++) pAp+=p[i]*Ap[i]; const al=rz/pAp;
    let rn=0; for(let i=0;i<S;i++){ x[i]+=al*p[i]; r[i]-=al*Ap[i]; rn+=r[i]*r[i]; } rn=Math.sqrt(rn)/bn; hist.push(rn); if(rn<(opt.tol||1e-8)) { it++; break; }
    let rz2=0; for(let i=0;i<S;i++){ z[i]=r[i]*Pinv[i]; rz2+=r[i]*z[i]; } const be=rz2/rz; rz=rz2; for(let i=0;i<S;i++) p[i]=z[i]+be*p[i]; }
  return {a:x, map:shtSynth(G,x), iter:it, residual:hist[hist.length-1], hist, fsky}; }

const WF_LNF=(()=>{ const f=new Float64Array(2000); for(let i=1;i<f.length;i++) f[i]=f[i-1]+Math.log(i); return f; })();

function wf3j2(l1,l2,l3){ const J=l1+l2+l3; if(J%2||l3<Math.abs(l1-l2)||l3>l1+l2) return 0; const g=J/2, F=WF_LNF;
  return Math.exp(F[J-2*l1]+F[J-2*l2]+F[J-2*l3]-F[J+1]+2*(F[g]-F[g-l1]-F[g-l2]-F[g-l3])); }

function masterCoupling(W,L){ const M=Array.from({length:L+1},()=>new Float64Array(L+1));
  for(let l=0;l<=L;l++) for(let lp=0;lp<=L;lp++){ let s=0; for(let l3=Math.abs(l-lp);l3<=Math.min(l+lp,W.length-1);l3++) s+=(2*l3+1)*W[l3]*wf3j2(l,lp,l3); M[l][lp]=(2*lp+1)/(4*Math.PI)*s; }
  return M; }

function masterSolve(M,y,lmin){ const L=M.length-1, n=L-lmin+1, A=[], b=[]; for(let i=0;i<n;i++){ A.push(Array.from(M[i+lmin].slice(lmin))); b.push(y[i+lmin]); }
  for(let c=0;c<n;c++){ let piv=c; for(let r=c+1;r<n;r++) if(Math.abs(A[r][c])>Math.abs(A[piv][c])) piv=r; [A[c],A[piv]]=[A[piv],A[c]]; [b[c],b[piv]]=[b[piv],b[c]];
    for(let r=c+1;r<n;r++){ const f=A[r][c]/A[c][c]; if(!f) continue; for(let k=c;k<n;k++) A[r][k]-=f*A[c][k]; b[r]-=f*b[c]; } }
  const x=new Float64Array(n); for(let r=n-1;r>=0;r--){ let s=b[r]; for(let k=r+1;k<n;k++) s-=A[r][k]*x[k]; x[r]=s/A[r][r]; }
  const out=new Float64Array(L+1); for(let i=0;i<n;i++) out[i+lmin]=x[i]; return out; }

function masterMaskCoeffs(maskFn,L2,fwhmDeg){ const Gm=shtGrid(2*L2,true), m=new Float64Array(Gm.nt*Gm.np);
  for(let j=0;j<Gm.nt;j++){ const ct=Gm.x[j], st=Math.sqrt(1-ct*ct); for(let k=0;k<Gm.np;k++){ const ph=2*Math.PI*k/Gm.np; m[j*Gm.np+k]=maskFn([st*Math.cos(ph), st*Math.sin(ph), ct]); } }
  const big=shtAnalysis(Gm,m), sg=(fwhmDeg||0)*Math.PI/180/Math.sqrt(8*Math.log(2)), w=new Float64Array((L2+1)*(L2+1));
  for(let l=0;l<=L2;l++){ const b=Math.exp(-0.5*l*(l+1)*sg*sg); for(let mm=-l;mm<=l;mm++) w[shtIdx(l,mm)]=big[shtIdx(l,mm)]*b; }
  return w; }

function masterPseudoCl(G2,a,L,w){ const L2=G2.L, pad=new Float64Array((L2+1)*(L2+1)); for(let l=0;l<=L;l++) for(let m=-l;m<=l;m++) pad[shtIdx(l,m)]=a[shtIdx(l,m)];
  const sm=shtSynth(G2,pad), mm=shtSynth(G2,w); for(let p=0;p<sm.length;p++) sm[p]*=mm[p]; const b=shtAnalysis(G2,sm), out=new Float64Array((L+1)*(L+1));
  for(let l=0;l<=L;l++) for(let m=-l;m<=l;m++) out[shtIdx(l,m)]=b[shtIdx(l,m)]; return shtCl(out,L); }

function wfExperiment(opt){ const L=opt.L||64, C=opt.C, G=shtGrid(L), A=shtPixArea(G), rnd=mulberry((opt.seed||1)^0x51ed), sigma2=C[Math.min(L,opt.lN||Math.round(0.8*L))];
  const holes=opt.holes||[], bDeg=opt.bDeg??20, truth=shtRealize(C,L,opt.seed||1), tmap=shtSynth(G,truth), mask=wfMask(G,bDeg,holes);
  const g=()=>{ let u=0; while(u===0) u=rnd(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*rnd()); };
  const d=new Float64Array(tmap.length); for(let p=0;p<d.length;p++) d[p]=mask[p]?tmap[p]+Math.sqrt(sigma2/A[p])*g():0;
  const W=wienerFilter(G,C,sigma2,mask,d,{tol:opt.tol||1e-7}), resid=tmap.map((v,p)=>v-W.map[p]);
  /* how well the holes are painted: the correlation of truth and Wiener sky over the masked pixels, area-weighted */
  const corr=(sel)=>{ let xy=0,xx=0,yy=0; for(let p=0;p<A.length;p++) if(sel(p)){ xy+=A[p]*tmap[p]*W.map[p]; xx+=A[p]*tmap[p]**2; yy+=A[p]*W.map[p]**2; } return xy/Math.sqrt(xx*yy); };
  const sb=Math.sin(bDeg*Math.PI/180), maskFn=n=>{ if(Math.abs(n[2])<sb) return 0; for(const h of holes) if(n[0]*h.c[0]+n[1]*h.c[1]+n[2]*h.c[2]>Math.cos(h.r*Math.PI/180)) return 0; return 1; };
  const w=masterMaskCoeffs(maskFn,2*L,opt.apo??4), M=masterCoupling(shtCl(w,2*L),L), fsky=w[0]/Math.sqrt(4*Math.PI), G2=shtGrid(2*L,2*L>128);
  const pc=masterPseudoCl(G2,truth,L,w), master=masterSolve(M,pc,2), naive=pc.map(v=>v/fsky), R=opt.R||0, mM=new Float64Array(L+1), mN=new Float64Array(L+1);
  for(let r=0;r<R;r++){ const p2=masterPseudoCl(G2,shtRealize(C,L,(opt.seed||1)*7919+r+1),L,w), e=masterSolve(M,p2,2); for(let l=2;l<=L;l++){ mM[l]+=e[l]/C[l]/R; mN[l]+=p2[l]/fsky/C[l]/R; } }
  return {L, G:{nt:G.nt, np:G.np, x:Array.from(G.x)}, truth:tmap, data:d, mask, wf:W.map, resid, iter:W.iter, residual:W.residual, fskyWF:W.fsky, fsky, sigma2,
    corrIn:corr(p=>!mask[p]), corrOut:corr(p=>!!mask[p]), C:Array.from(C), pseudo:Array.from(pc), master:Array.from(master), naive:Array.from(naive), mcMaster:Array.from(mM), mcNaive:Array.from(mN), R}; }

const C_DH_GLY = 299792.458/67.4/306.601;

