    dRes+=(divR-tR)**2+(divI-tI)**2; dNorm+=tR*tR+tI*tI;
    const cx=[kb*Z.re[i]-kc*Y.re[i], kb*Z.im[i]-kc*Y.im[i]], cy=[kc*X.re[i]-ka*Z.re[i], kc*X.im[i]-ka*Z.im[i]], cz=[ka*Y.re[i]-kb*X.re[i], ka*Y.im[i]-kb*X.im[i]];
