    r=(B[0]*(B[3]*B[5]-B[4]*B[4])-B[1]*(B[1]*B[5]-B[4]*B[2])+B[2]*(B[1]*B[4]-B[3]*B[2]))/2, ph=r<=-1?Math.PI/3:r>=1?0:Math.acos(r)/3,
