function burgersHopfCole(x,t,nu,psi0,qa,qb,n){ n=n||4000; const h=(qb-qa)/n, G=new Float64Array(n+1); let gmin=Infinity;
  for(let i=0;i<=n;i++){ const q=qa+i*h; G[i]=psi0(q)+(x-q)*(x-q)/(2*t); if(G[i]<gmin) gmin=G[i]; }
  let Z=0, Q=0; for(let i=0;i<=n;i++){ const w=Math.exp(-(G[i]-gmin)/(2*nu))*((i===0||i===n)?0.5:1); Z+=w; Q+=w*(qa+i*h); }
  const qs=Q/Z; return {u:(x-qs)/t, q:qs}; }

