function galOrbit(d,v,P){ P=P||GAL_RIDE; const K=P.KMS, S=P.sunUVW, x=d[0]-P.R0, y=d[1], ux=(v[0]+S[0])*K, uy=(v[1]+S[1])*K+P.Om*P.R0;
  return {T:galTorus(x,y,ux,uy,P,16), x, y, ux, uy, z0:d[2], w0:(v[2]+S[2])*K/P.nu}; }

function galOrbitAt(o,t,P){ P=P||GAL_RIDE; const Z=o.z0*Math.cos(P.nu*t)+o.w0*Math.sin(P.nu*t);
  if(!o.T) return [o.x+o.ux*t, o.y+o.uy*t, Z];             /* unbound in the model: a straight line */
  const q=galTorusAt(o.T,t); return [q[0]*Math.cos(q[1]), q[0]*Math.sin(q[1]), Z]; }

const GAL_SUN_ORBIT=new WeakMap();

function galSunOrbit(P){ P=P||GAL_RIDE; let o=GAL_SUN_ORBIT.get(P); if(!o){ o=galOrbit([0,0,0],[0,0,0],P); GAL_SUN_ORBIT.set(P,o); } return o; }

function galRideOrbit(o,t,P){ const a=galOrbitAt(o,t,P), b=galOrbitAt(galSunOrbit(P),t,P); return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }

function galRide(d,v,tMyr,P){ return galRideOrbit(galOrbit(d,v,P),tMyr,P); }

function galRideHalo(d,tMyr,P){ P=P||GAL_RIDE; const b=galOrbitAt(galSunOrbit(P),tMyr,P); return [d[0]-P.R0-b[0], d[1]-b[1], d[2]-b[2]]; }

