function dtAgeGyrAtA(a,C){ C=C||DT_COSMO; return 2/(3*Math.sqrt(C.OL)*C.H0)*Math.asinh(Math.sqrt(C.OL/C.Om)*Math.pow(a,1.5)); }

function dtAgeGyrAtLnA(lnA,C){ C=C||DT_COSMO; const y=0.5*Math.log(C.OL/C.Om)+1.5*lnA, as=y>20?y+Math.LN2:Math.asinh(Math.exp(y));
  return 2/(3*Math.sqrt(C.OL)*C.H0)*as; }

const DT_T0_GYR=dtAgeGyrAtA(1);

function dtCmbLog10K(yearsFromNow,C){ C=C||DT_COSMO; return Math.log10(C.T0)-dtLnA(DT_T0_GYR+yearsFromNow/1e9,C)/Math.LN10; }

