const BBH_G=6.67430e-11, BBH_C=299792458, BBH_MSUN=1.98892e30, BBH_YR=365.25*86400;

function bbhParams(m1,m2){ const M=m1+m2, q=Math.min(m1,m2)/Math.max(m1,m2), eta=m1*m2/(M*M); return {M, q, eta, Mc:Math.pow(m1*m2,3/5)/Math.pow(M,1/5)}; }

