function lgNucleusAt(O,years){ const T=lgMergerTimeline(O);
  if(years<T.tGal) return {phase:'approach', T};
  if(years<T.tBH) return {phase:'sinking', rKpc:LG_NUCLEUS.r0Kpc*Math.sqrt(1-(years-T.tGal)/T.tDf), T};
  return {phase:'merged', since:years-T.tBH, frontLy:(years-T.tBH), T}; }

