    const mw={...LGM_GAL.mw, Mh:LGM_GAL.mw.Mh*fm, ah:LGM_GAL.mw.ah*Math.cbrt(fm)}, m31={...LGM_GAL.m31, Mh:LGM_GAL.m31.Mh*fa, ah:LGM_GAL.m31.ah*Math.cbrt(fa)};
