    const o=lgmOrbit({mw, m31, dKpc:LGM_OBS.dKpc+S.dKpc*g(), vRad:LGM_OBS.vRad+S.vRad*g(), vTan:vt, tGyr:tGyr||14, dtMyr:1, outMyr:20}), e=lgmEvents(o,12);
