const LGM_GC=Object.freeze({raDeg:266.405, decDeg:-28.936, dKpc:8.178});

const LGM_NGP=Object.freeze({raDeg:192.85948, decDeg:27.12825});

const LGM_M31=Object.freeze({raDeg:10.684708, decDeg:41.26875, dKpc:778.0, inclDeg:77.5, paDeg:38.0});

function lgmUnit(ra,dec){ const a=ra*Math.PI/180, d=dec*Math.PI/180; return [Math.cos(d)*Math.cos(a), Math.cos(d)*Math.sin(a), Math.sin(d)]; }

const lgmCross=(a,b)=>[a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]], lgmDot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];

const lgmNorm=a=>{ const l=Math.hypot(a[0],a[1],a[2]); return [a[0]/l,a[1]/l,a[2]/l]; };

function lgmGeometry(){ const gc=lgmUnit(LGM_GC.raDeg,LGM_GC.decDeg).map(c=>c*LGM_GC.dKpc), um=lgmUnit(LGM_M31.raDeg,LGM_M31.decDeg), m31=um.map(c=>c*LGM_M31.dKpc);
  const rel=[m31[0]-gc[0], m31[1]-gc[1], m31[2]-gc[2]], d=Math.hypot(...rel), ex=rel.map(c=>c/d), ngp=lgmUnit(LGM_NGP.raDeg,LGM_NGP.decDeg);
  const ey=lgmNorm(ngp.map((c,i)=>c-lgmDot(ngp,ex)*ex[i]));                                  /* in the plane of the pole */
  /* M31's disc: the line of sight u, north and east on its sky, the minor axis; the normal cos i·u + sin i·e_minor */
  const eN=lgmNorm([-Math.sin(LGM_M31.decDeg*Math.PI/180)*Math.cos(LGM_M31.raDeg*Math.PI/180), -Math.sin(LGM_M31.decDeg*Math.PI/180)*Math.sin(LGM_M31.raDeg*Math.PI/180), Math.cos(LGM_M31.decDeg*Math.PI/180)]);
  const eE=lgmCross(eN,um), pa=LGM_M31.paDeg*Math.PI/180, eMaj=eN.map((c,i)=>Math.cos(pa)*c+Math.sin(pa)*eE[i]), eMin=eN.map((c,i)=>-Math.sin(pa)*c+Math.cos(pa)*eE[i]);
  const inc=LGM_M31.inclDeg*Math.PI/180; let nM=lgmNorm(um.map((c,i)=>Math.cos(inc)*c+Math.sin(inc)*eMin[i]));
  /* the north-east end of the major axis recedes: the rotation L̂ × ê_maj must point away from us */
  if(lgmDot(lgmCross(nM,eMaj),um)<0) nM=nM.map(c=>-c);
  const nMW=ngp.map(c=>-c);                                                                   /* the Sun's sense of rotation */
  return {dKpc:d, ex, ey, nMW, nM31:nM, gc, m31}; }

function lgmSampleDisc(g,n,N,rnd,rmax){ const e1=lgmNorm(Math.abs(n[2])<0.9?lgmCross(n,[0,0,1]):lgmCross(n,[1,0,0])), e2=lgmCross(n,e1), a=[0,0,0], P=[], V=[];
  const nb=Math.round(N*g.Mb/(g.Md+g.Mb)*0.6);
  for(let i=0;i<N;i++){ let R, z, ph=2*Math.PI*rnd(), p, bulge=i<nb;
    if(bulge){ const u=Math.min(0.98,rnd()), rr=g.ab*Math.sqrt(u)/(1-Math.sqrt(u)), ct=2*rnd()-1, st=Math.sqrt(1-ct*ct); p=[rr*st*Math.cos(ph), rr*st*Math.sin(ph), rr*ct].map((c,k)=>c); p=[p[0]*e1[0]+p[1]*e2[0]+p[2]*n[0], p[0]*e1[1]+p[1]*e2[1]+p[2]*n[1], p[0]*e1[2]+p[1]*e2[2]+p[2]*n[2]]; }
    else { do{ R=-g.Rd*Math.log(rnd()*rnd()); }while(R>rmax); z=g.bd*0.5*Math.log(rnd()/(1-rnd()+1e-12))*0.5; p=e1.map((c,k)=>R*Math.cos(ph)*c+R*Math.sin(ph)*e2[k]+z*n[k]); }
    lgmAccel(g,n,p[0],p[1],p[2],a); const zeta=lgmDot(p,n), pr=p.map((c,k)=>c-zeta*n[k]), Rn=Math.hypot(...pr)+1e-6;
    const vc=Math.sqrt(Math.max(0,-lgmDot(a,pr)/Rn*Rn)), t=lgmNorm(lgmCross(n,pr));
    const s=bulge?0.55*vc+20:0.08*vc+8, gs=()=>{ const u=Math.max(1e-12,rnd()); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*rnd()); };
    P.push(p); V.push(bulge?[s*gs(),s*gs(),s*gs()]:t.map(c=>c*vc*(1-0.04*rnd())).map(c=>c+s*gs()*0.4)); }
  return {P,V}; }

function lgmStars(opt){ opt=opt||{}; const Gm=lgmGeometry(), A=LGM_GAL.mw, B=LGM_GAL.m31, MA=lgmTotalMass(A), MB=lgmTotalMass(B), fA=MB/(MA+MB), fB=MA/(MA+MB);
  const orb=lgmOrbit({vTan:opt.vTan??LGM_OBS.vTan, dKpc:Gm.dKpc, tGyr:opt.tGyr??12, dtMyr:opt.dtMyr||1, outMyr:opt.dtMyr||1});
  const cen=k=>{ const o=orb[Math.min(k,orb.length-1)], r=[o.x*Gm.ex[0]+o.y*Gm.ey[0], o.x*Gm.ex[1]+o.y*Gm.ey[1], o.x*Gm.ex[2]+o.y*Gm.ey[2]];
    return {A:r.map(c=>-c*fA), B:r.map(c=>c*fB)}; };
  const rnd=mulberry(opt.seed||31), nA=opt.nMW||1500, nB=opt.nM31||1500, dA=lgmSampleDisc(A,Gm.nMW,nA,rnd,18), dB=lgmSampleDisc(B,Gm.nM31,nB,rnd,26);
  const c0=cen(0), o0=orb[0], vrel=[0,0,0];
  { const o1=orb[1], dt=(o1.tGyr-o0.tGyr)/LGM_GYR; const r0=[o0.x,o0.y], r1=[o1.x,o1.y]; for(let k=0;k<3;k++) vrel[k]=((r1[0]-r0[0])*Gm.ex[k]+(r1[1]-r0[1])*Gm.ey[k])/dt; }
  const N=nA+nB, P=new Float64Array(N*3), V=new Float64Array(N*3);
  for(let i=0;i<nA;i++) for(let k=0;k<3;k++){ P[i*3+k]=dA.P[i][k]+c0.A[k]; V[i*3+k]=dA.V[i][k]-vrel[k]*fA; }
  for(let i=0;i<nB;i++) for(let k=0;k<3;k++){ P[(nA+i)*3+k]=dB.P[i][k]+c0.B[k]; V[(nA+i)*3+k]=dB.V[i][k]+vrel[k]*fB; }
  const h=(opt.dtMyr||1)/1000/LGM_GYR, steps=orb.length-1, every=Math.round((opt.outMyr||25)/(opt.dtMyr||1)), frames=[], centres=[], a=[0,0,0], b=[0,0,0];
  const accAll=(k,out)=>{ const c=cen(k); for(let i=0;i<N;i++){ const x=P[i*3], y=P[i*3+1], z=P[i*3+2];
      lgmAccel(A,Gm.nMW,x-c.A[0],y-c.A[1],z-c.A[2],a); lgmAccel(B,Gm.nM31,x-c.B[0],y-c.B[1],z-c.B[2],b);
      out[i*3]=a[0]+b[0]; out[i*3+1]=a[1]+b[1]; out[i*3+2]=a[2]+b[2]; } };
  const acc=new Float64Array(N*3); accAll(0,acc);
  const snap=k=>{ const f=new Float32Array(N*3); for(let i=0;i<N*3;i++) f[i]=P[i]; frames.push(f); const c=cen(k); centres.push({tGyr:orb[k].tGyr, A:c.A, B:c.B, rKpc:orb[k].rKpc}); };
  snap(0); if(opt.onFrame) opt.onFrame(0, frames[0], centres[0]);
  for(let k=0;k<steps;k++){ for(let i=0;i<N*3;i++){ V[i]+=0.5*h*acc[i]; P[i]+=h*V[i]; } accAll(k+1,acc); for(let i=0;i<N*3;i++) V[i]+=0.5*h*acc[i];
    if((k+1)%every===0){ snap(k+1); if(opt.onFrame) opt.onFrame(frames.length-1, frames[frames.length-1], centres[centres.length-1]); } if(opt.progress&&(k%200===0)) opt.progress(k/steps); }
  return {nMW:nA, nM31:nB, frames, centres, outMyr:opt.outMyr||25, orbit:orb, events:lgmEvents(orb,12), geometry:Gm}; }

