  const k1=nsgLamb(B,a), a2=a.map((x,i)=>E[i]*(x+h/2*k1[i])), k2=nsgLamb(B,a2), a3=a.map((x,i)=>E[i]*x+h/2*k2[i]), k3=nsgLamb(B,a3), a4=a.map((x,i)=>E2[i]*x+h*E[i]*k3[i]), k4=nsgLamb(B,a4);
