  F04327:{lab:'nsgal', what:['the Korn ladder 2‖Def u‖²/‖u‖² = k(k+4) by quadrature','лестница Корна по квадратуре','Korn-Leiter'], run:()=>fcKornLadder()},
  F04618:{lab:'s3lock', what:['a Hopf filament and its 𝒥-partner: Hausdorff gap 2√min(c, 1 − c)','нить Хопфа и её 𝒥-пара: зазор Хаусдорфа 2√min(c, 1 − c)','Paarungslücke'], run:()=>fcPairGap()},
  F03599:{lab:'s3lock', what:['the Weyl–zeta residue of the Stokes spectrum → 2/3 (per volume 1/(3π²))','вычет Вейля–дзета спектра Стокса → 2/3','Zeta-Residuum'], run:()=>fcZetaResidue()},
  F00007:{lab:null, what:['the boxed rational counting law of Λ_h — tested below and above the Frobenius threshold','выделенный рациональный закон счёта Λ_h — ниже и выше порога Фробениуса','Zählgesetz'], run:()=>fcMonoidRational()},
  F04069:{lab:'s3lock', what:['route P₁: 𝒥-parity of the stretching of a 𝒥-symmetric field','маршрут P₁: 𝒥-чётность растяжения 𝒥-симметричного поля','Route P₁'], run:()=>fcStretchParity()},
  F00233:{lab:'s3lock', what:['the shell commutator bound ‖[u_α,u_β]‖ ≤ C(k_αk_β)^{1/2}‖u_α‖‖u_β‖','оценка коммутатора оболочек','Kommutatorschranke'], run:()=>fcCommutatorBound()},
  F03574:{lab:'nsgal', what:['inf Γ_N > 0: is there a Diophantine gap between Stokes phases?','inf Γ_N > 0: есть ли диофантов зазор между фазами Стокса?','Diophantische Lücke'], run:()=>fcExactTriads()},
