const FRAC_RULES={
  menger:{name:'Menger sponge', r:3, solid:'box',
    cells:(()=>{const o=[];for(let x=0;x<3;x++)for(let y=0;y<3;y++)for(let z=0;z<3;z++){
      if(((x===1)+(y===1)+(z===1))<=1) o.push([x,y,z]); } return o;})(),
    note:'the 3×3×3 cube with the middle of every face and the centre removed — twenty copies of itself'},
  carpet:{name:'Sierpiński carpet', r:3, solid:'box',
    cells:(()=>{const o=[];for(let x=0;x<3;x++)for(let y=0;y<3;y++) if(!(x===1&&y===1)) o.push([x,y,0]); return o;})(),
    note:'the same removal in the plane: eight copies, and a dimension between a curve and a surface'},
  dust:{name:'Cantor dust', r:3, solid:'box',
    cells:(()=>{const o=[];for(const x of[0,2])for(const y of[0,2])for(const z of[0,2]) o.push([x,y,z]); return o;})(),
    note:'the Cantor set cubed — eight corners, totally disconnected, and EXACTLY the dimension of the carpet'},
  vicsek:{name:'Vicsek cross', r:3, solid:'box',
    cells:[[1,1,1],[0,1,1],[2,1,1],[1,0,1],[1,2,1],[1,1,0],[1,1,2]],
    note:'a centre and its six face neighbours: connected where the dust is not, and lower-dimensional than either'},
  tetra:{name:'Sierpiński tetrahedron', r:2, solid:'tetra',
    cells:[[0,0,0],[1,0,0],[0,1,0],[0,0,1]],
    note:'four half-scale copies at the corners — dimension exactly 2, a fractal that is not fractional at all'}
};

const fracDimension=(N,r)=>Math.log(N)/Math.log(r);

const fracExactDimension=k=>{const R=FRAC_RULES[k]; return fracDimension(R.cells.length,R.r);};

function fracBuild(kind,depth){
  const R=FRAC_RULES[kind]; if(!R) return {pts:[],size:1};
  let pts=[[0,0,0]], s=1;
  for(let d=0;d<depth;d++){ const nx=[]; s/=R.r;
    for(let i=0;i<pts.length;i++){ const p=pts[i];
      for(let j=0;j<R.cells.length;j++){ const c=R.cells[j];
        nx.push([p[0]+c[0]*s, p[1]+c[1]*s, p[2]+c[2]*s]); } }
    pts=nx; }
  /* CENTRES, not corners. A corner lies exactly on a box boundary and floor() then splits
     it unpredictably — which is what made the first box-counting measurement of this
     return 2.50 for a sponge whose dimension is 2.727. */
  return {pts:pts.map(q=>[q[0]+s/2,q[1]+s/2,q[2]+s/2]), size:s};
}

function fracBoxCount(pts,eps){
  const seen=new Set();
  for(let i=0;i<pts.length;i++)
    seen.add(Math.floor(pts[i][0]/eps)+'|'+Math.floor(pts[i][1]/eps)+'|'+Math.floor(pts[i][2]/eps));
  return seen.size;
}

function fracMeasuredDimension(kind,depth){
  const R=FRAC_RULES[kind], {pts}=fracBuild(kind,depth);
  const e1=Math.pow(1/R.r,Math.max(1,depth-2)), e2=Math.pow(1/R.r,depth);
  const n1=fracBoxCount(pts,e1), n2=fracBoxCount(pts,e2);
  return Math.log(n2/n1)/Math.log(e1/e2);
}

const fracCellCount=(kind,depth)=>Math.pow(FRAC_RULES[kind].cells.length,depth);

const FS_TETS=[[0,1,3,7],[0,3,2,7],[0,2,6,7],[0,6,4,7],[0,4,5,7],[0,5,1,7]];

function fsGrad(q,N){ const L=N*N, n=q.length, gx=new Float32Array(n), gy=new Float32Array(n), gz=new Float32Array(n);
  for(let z=0;z<N;z++) for(let y=0;y<N;y++) for(let x=0;x<N;x++){ const i=(z*N+y)*N+x;
    gx[i]=x===0?q[i+1]-q[i]:x===N-1?q[i]-q[i-1]:(q[i+1]-q[i-1])/2;
    gy[i]=y===0?q[i+N]-q[i]:y===N-1?q[i]-q[i-N]:(q[i+N]-q[i-N])/2;
    gz[i]=z===0?q[i+L]-q[i]:z===N-1?q[i]-q[i-L]:(q[i+L]-q[i-L])/2; }
  return [gx,gy,gz]; }

function fsIso(q,N,iso,G,s,phase){ G=G||fsGrad(q,N); s=s||1; const L=N*N, h=(N-1)/2, P=[], Nn=[], C=phase?[]:null; let area=0, vol=0, flux=0;
  const cx=[0,1,0,1,0,1,0,1], cy=[0,0,1,1,0,0,1,1], cz=[0,0,0,0,1,1,1,1], off=cx.map((_,k)=>cx[k]+cy[k]*N+cz[k]*L), cv=new Float64Array(8);
  const vtx=(base,x,y,z,a,b,out)=>{ const ia=base+off[a], ib=base+off[b], va=cv[a], vb=cv[b], t=va===vb?0.5:(iso-va)/(vb-va);
    out[0]=(x+cx[a]+t*(cx[b]-cx[a])-h)*s; out[1]=(y+cy[a]+t*(cy[b]-cy[a])-h)*s; out[2]=(z+cz[a]+t*(cz[b]-cz[a])-h)*s;
    let nx=-(G[0][ia]+t*(G[0][ib]-G[0][ia])), ny=-(G[1][ia]+t*(G[1][ib]-G[1][ia])), nz=-(G[2][ia]+t*(G[2][ib]-G[2][ia])); const m=Math.hypot(nx,ny,nz);
    /* a vertex on a plateau has no gradient; it takes its triangle's normal below — a zero normal is NaN in a shader, and one NaN pixel blurred by bloom blacks out the frame */
    if(m>1e-12){ out[3]=nx/m; out[4]=ny/m; out[5]=nz/m; } else { out[3]=0; out[4]=0; out[5]=0; } out[7]=m; if(phase) out[6]=phase[ia]+t*(phase[ib]-phase[ia]); };
  const A=new Float64Array(8), B=new Float64Array(8), D=new Float64Array(8);
  const tri=(p,q2,r)=>{ const ux=q2[0]-p[0], uy=q2[1]-p[1], uz=q2[2]-p[2], wx=r[0]-p[0], wy=r[1]-p[1], wz=r[2]-p[2];
    let fx=uy*wz-uz*wy, fy=uz*wx-ux*wz, fz=ux*wy-uy*wx; const fa=Math.hypot(fx,fy,fz); if(!(fa>0)) return;
    /* oriented to −∇u: out of the region where u > iso, so the divergence theorem gives its volume */
    let a=p, b=q2, c=r; const flip=fx*(p[3]+q2[3]+r[3])+fy*(p[4]+q2[4]+r[4])+fz*(p[5]+q2[5]+r[5])<0; if(flip){ b=r; c=q2; }
    const sg=(flip?-1:1)/fa;
    for(const v of [a,b,c]){ P.push(v[0],v[1],v[2]); if(v[3]||v[4]||v[5]) Nn.push(v[3],v[4],v[5]); else Nn.push(fx*sg,fy*sg,fz*sg); if(C) C.push(v[6]); }
    /* the flux of −∇u out through this triangle: |∇u| n̂_v at each vertex, projected on the face */
    const nfx=fx*sg, nfy=fy*sg, nfz=fz*sg; flux+=fa/2*[a,b,c].reduce((t,v)=>t+v[7]*(v[3]*nfx+v[4]*nfy+v[5]*nfz),0)/3;
    area+=fa/2; vol+=(a[0]*(b[1]*c[2]-b[2]*c[1])+a[1]*(b[2]*c[0]-b[0]*c[2])+a[2]*(b[0]*c[1]-b[1]*c[0]))/6; };
  for(let z=0;z<N-1;z++) for(let y=0;y<N-1;y++) for(let x=0;x<N-1;x++){ const base=(z*N+y)*N+x; let lo=0, hi=0;
    for(let k=0;k<8;k++){ const v=q[base+off[k]]; cv[k]=v; if(v>iso) hi++; else lo++; } if(!hi||!lo) continue;
    for(const T of FS_TETS){ const ins=T.filter(k=>cv[k]>iso), out=T.filter(k=>!(cv[k]>iso));
      if(ins.length===1||ins.length===3){ const a=ins.length===1?ins[0]:out[0], o=ins.length===1?out:ins;
        vtx(base,x,y,z,a,o[0],A); vtx(base,x,y,z,a,o[1],B); vtx(base,x,y,z,a,o[2],D); tri(A,B,D); }
      else if(ins.length===2){ const [a,b]=ins, [c,d]=out, E1=new Float64Array(8), E2=new Float64Array(8), E3=new Float64Array(8), E4=new Float64Array(8);
        vtx(base,x,y,z,a,c,E1); vtx(base,x,y,z,a,d,E2); vtx(base,x,y,z,b,d,E3); vtx(base,x,y,z,b,c,E4); tri(E1,E2,E3); tri(E1,E3,E4); } } }
  return {pos:Float32Array.from(P), nrm:Float32Array.from(Nn), phase:C?Float32Array.from(C):null, vertices:P.length/3, area, volume:vol, flux}; }

function fsWolff(L,T,therm,meas,seed){ const N=L*L*L, L2=L*L, s=new Int8Array(N).fill(1), stack=new Int32Array(N); let r=(seed>>>0)||1;
  const rnd=()=>{ r^=r<<13; r^=r>>>17; r^=r<<5; return (r>>>0)/4294967296; }, p=1-Math.exp(-2/T); let M=N;
  const step=()=>{ const i0=(rnd()*N)|0, s0=s[i0]; let top=0, size=1; stack[top++]=i0; s[i0]=-s0;
    while(top){ const i=stack[--top], x=i%L, y=((i/L)|0)%L, z=(i/L2)|0;
      const nb0=z*L2+y*L+(x+1)%L, nb1=z*L2+y*L+(x+L-1)%L, nb2=z*L2+((y+1)%L)*L+x, nb3=z*L2+((y+L-1)%L)*L+x, nb4=((z+1)%L)*L2+y*L+x, nb5=((z+L-1)%L)*L2+y*L+x;
      for(const j of [nb0,nb1,nb2,nb3,nb4,nb5]) if(s[j]===s0&&rnd()<p){ s[j]=-s0; stack[top++]=j; size++; } }
    M-=2*s0*size; };
  for(let k=0;k<therm;k++) step();
  let m2=0, m4=0, ma=0; for(let k=0;k<meas;k++){ step(); const m=M/N; m2+=m*m; m4+=m*m*m*m; ma+=Math.abs(m); }
  m2/=meas; m4/=meas; ma/=meas; return {L,T,U:1-m4/(3*m2*m2), chi:N*(m2-ma*ma)/T, m:ma}; }

function fsCrossing(Ts,Ua,Ub){ for(let i=0;i+1<Ts.length;i++){ const d0=Ua[i]-Ub[i], d1=Ua[i+1]-Ub[i+1]; if(d0===0) return {T:Ts[i],U:Ua[i]}; if(d0*d1<0){ const f=d0/(d0-d1); return {T:Ts[i]+f*(Ts[i+1]-Ts[i]), U:Ua[i]+f*(Ua[i+1]-Ua[i])}; } } return null; }

function fsWidest(S){ if(!S||S.length<3) return null; let k=0; for(let i=1;i<S.length;i++) if(S[i].V>S[k].V) k=i; if(k===0||k===S.length-1) return null;
  const [a,b,c]=[S[k-1],S[k],S[k+1]], den=(a.t-b.t)*(a.t-c.t)*(b.t-c.t); if(!den) return null;
  const A=(c.t*(b.V-a.V)+b.t*(a.V-c.V)+a.t*(c.V-b.V))/den, B=(c.t*c.t*(a.V-b.V)+b.t*b.t*(c.V-a.V)+a.t*a.t*(b.V-c.V))/den; if(!(A<0)) return null;
  const ts=-B/(2*A), Vs=(A*ts+B)*ts+((a.V-(A*a.t+B)*a.t)), j=ts<b.t?k-1:k, u=S[j], w=S[j+1], r2=u.r2+(w.r2-u.r2)*(ts-u.t)/(w.t-u.t);
  const req2=Math.pow(3*Vs/(4*Math.PI),2/3); return {t:ts, V:Vs, req2, r2, ratio:req2/r2}; }

function fsTri(q,N,x,y,z){ const m=N-1-1e-9; x=Math.min(m,Math.max(0,x)); y=Math.min(m,Math.max(0,y)); z=Math.min(m,Math.max(0,z));
  const i=Math.floor(x), j=Math.floor(y), k=Math.floor(z), fx=x-i, fy=y-j, fz=z-k, L=N*N, b=(k*N+j)*N+i;
  const c00=q[b]*(1-fx)+q[b+1]*fx, c10=q[b+N]*(1-fx)+q[b+N+1]*fx, c01=q[b+L]*(1-fx)+q[b+L+1]*fx, c11=q[b+L+N]*(1-fx)+q[b+L+N+1]*fx;
  return (c00*(1-fy)+c10*fy)*(1-fz)+(c01*(1-fy)+c11*fy)*fz; }

function fsFieldLine(G,N,seed,sign,opts){ opts=opts||{}; const h=opts.h||0.35, maxS=opts.maxSteps||420, lo=opts.lo??0.5, hi=N-1-(opts.lo??0.5), pts=[seed.slice()];
  const dir=p=>{ const gx=fsTri(G[0],N,p[0],p[1],p[2]), gy=fsTri(G[1],N,p[0],p[1],p[2]), gz=fsTri(G[2],N,p[0],p[1],p[2]), m=Math.hypot(gx,gy,gz); return m>(opts.tiny||1e-9)?[sign*gx/m,sign*gy/m,sign*gz/m,m]:null; };
  let p=seed.slice();
  for(let n=0;n<maxS;n++){ const k1=dir(p); if(!k1) break; const p2=p.map((v,i)=>v+h/2*k1[i]), k2=dir(p2); if(!k2) break; const p3=p.map((v,i)=>v+h/2*k2[i]), k3=dir(p3); if(!k3) break;
    const p4=p.map((v,i)=>v+h*k3[i]), k4=dir(p4); if(!k4) break; p=p.map((v,i)=>v+h/6*(k1[i]+2*k2[i]+2*k3[i]+k4[i]));
    if(p.some(v=>v<lo||v>hi)) break; pts.push(p.slice()); if(opts.stop&&opts.stop(p)) break; }
  return pts; }

function fsIsingWalls(sp,N){ const faces=[]; let W=0;
  for(let z=0;z<N;z++) for(let y=0;y<N;y++) for(let x=0;x<N;x++){ const i=(z*N+y)*N+x, s=sp[i];
    const nb=[((z*N+y)*N+(x+1)%N),((z*N+(y+1)%N)*N+x),((((z+1)%N)*N+y)*N+x)];
    for(let a=0;a<3;a++) if(sp[nb[a]]!==s){ W++; faces.push(x,y,z,a); } }
  return {W,faces}; }

function fsColor(t){ const a=Math.min(1,Math.abs(t));
  if(t>=0) return [0.10+0.90*Math.min(1,a*1.5), 0.10+0.62*a+0.25*Math.max(0,a-0.6), 0.14+0.10*a+0.45*Math.max(0,a-0.75)];
  return [0.08+0.18*Math.max(0,a-0.7), 0.12+0.66*a, 0.18+0.82*Math.min(1,a*1.4)]; }

function fsSliceRGBA(q,N,axis,f,S,scale,levels){ const out=new Uint8Array(S*S*4), V=new Float64Array(S*S), c=f*(N-1);
  for(let j=0;j<S;j++) for(let i=0;i<S;i++){ const a=i/(S-1)*(N-1), b=j/(S-1)*(N-1); V[j*S+i]=axis===0?fsTri(q,N,c,a,b):axis===1?fsTri(q,N,a,c,b):fsTri(q,N,a,b,c); }
  for(let j=0;j<S;j++) for(let i=0;i<S;i++){ const v=V[j*S+i], col=fsColor(v/(scale||1)); let line=false;
    if(levels) for(const L0 of levels){ const r=i<S-1?V[j*S+i+1]:v, d=j<S-1?V[(j+1)*S+i]:v; if((v-L0)*(r-L0)<0||(v-L0)*(d-L0)<0){ line=true; break; } }
    const o=(j*S+i)*4; out[o]=Math.round(255*(line?Math.min(1,col[0]*0.35+0.65):col[0])); out[o+1]=Math.round(255*(line?Math.min(1,col[1]*0.35+0.65):col[1])); out[o+2]=Math.round(255*(line?Math.min(1,col[2]*0.35+0.65):col[2]));
    out[o+3]=line?250:Math.round(90+150*Math.min(1,Math.abs(v)/(scale||1))); }
  return out; }

const LAB_SKETCHES=new Set(['anyon','sec','red','lab','cp','noe','disp','qcd','nuosc','scales','grav','origins','rungs','wind','gyro','cosmo','phot','resolve','clock','phorizon','anyzoo','sbright','tscale','eos','photon','infolab','galrot','exo','seis','jonesq','qregime','s3escape','gate','osc','mimg','jeans','sn','spin']);

const LAB_CHAPTERS=Object.freeze({
  navier:['nsflow','nsgal','triad','vstretch','nsblow','strobe','omnistrobe','s3shell','s3kb','s3tube','s3torus','s3lock','formulas'],
  s3light:['gmode','nbg','unify','tri','hopf','s3gamma','discover']});

const LAB_DOMAIN_ORDER=['navier','s3light','invariance','geometry','dynamics','quantum','waves','thermo','astro','other','sketch'];

function xrLabIds(){
  const all=Object.keys(S3_VIEW_NAMES);
  const seen=new Set();
  const out=[];
  for(const d of LAB_DOMAIN_ORDER) for(const v of all)
    if(!seen.has(v)&&labDomainOf(v)===d){ seen.add(v); out.push(v); }
  for(const v of all) if(!seen.has(v)){ seen.add(v); out.push(v); }   // nothing may fall out
  return out;
}

function xrLabHeadCounts(){
  if(xrLabHeadCounts._c) return xrLabHeadCounts._c;
  const c=new Map();
  for(const id of Object.keys(S3_VIEW_NAMES)){
    const t=String(S3_VIEW_NAMES[id]||id), d=t.indexOf(' · ');
    const h=(d>0?t.slice(0,d):t).toLowerCase();
    c.set(h,(c.get(h)||0)+1);
  }
  xrLabHeadCounts._c=c; return c;
}

function xrLabShort(v,max){
  const M=max||20;
  const full=String((S3_VIEW_NAMES&&S3_VIEW_NAMES[v])||v);
  const d=full.indexOf(' · ');
  let t=full;
  if(d>0){
    const head=full.slice(0,d), tail=full.slice(d+3);
    /* the shared head is the useless one — "CIVP", "S³" — so take the tail there */
    t=(xrLabHeadCounts().get(head.toLowerCase())||0)>1 ? tail : head;
  }
  t=t.trim();
  if(t.length<=M) return t;
  const cut=t.lastIndexOf(' ',M-1);
  return (cut>=10?t.slice(0,cut):t.slice(0,M-1))+'…';
}

const XR_DOM_SHORT={invariance:'⟲ Invar',geometry:'◇ Geom',dynamics:'↻ Dyn',quantum:'⚛ Quant',
  waves:'∿ Waves',thermo:'♨ Therm',astro:'✦ Astro',other:'· Other',sketch:'✎ Sketch'};

function xrDomShort(d){ return XR_DOM_SHORT[d]||d; }

function xrLabPickerPlan(opt){
  const o=opt||{};
  const labs=o.labs||xrLabIds();
  const perPage=o.perPage||9, perRow=o.perRow||3;
  const doms=LAB_DOMAIN_ORDER.filter(d=>labs.some(v=>labDomainOf(v)===d));
  const domain=doms.includes(o.domain)?o.domain:doms[0];
  const mine=labs.filter(v=>labDomainOf(v)===domain);
  const pages=Math.max(1,Math.ceil(mine.length/perPage));
  const page=((o.page|0)%pages+pages)%pages;
  const items=mine.slice(page*perPage,page*perPage+perPage);
  const rows=[];
  for(let i=0;i<doms.length;i+=perRow)
    rows.push(doms.slice(i,i+perRow).map(d=>({kind:'domain', id:d,
      label:xrDomShort(d)+' '+labs.filter(v=>labDomainOf(v)===d).length, on:d===domain})));
  for(let i=0;i<items.length;i+=perRow)
    rows.push(items.slice(i,i+perRow).map(v=>({kind:'lab', id:v,
      label:xrLabShort(v), on:v===o.current})));
  if(pages>1) rows.push([{kind:'prev',id:'prev',label:'‹ prev'},
                         {kind:'page',id:'page',label:(page+1)+' / '+pages},
                         {kind:'next',id:'next',label:'next ›'}]);
  return {domain, domains:doms, page, pages, items, rows};
}

let xrLabRecent=[];

function xrLabRemember(v){
  if(!v||!S3_VIEW_NAMES[v]) return xrLabRecent;
  xrLabRecent=[v,...xrLabRecent.filter(x=>x!==v)].slice(0,8);
  return xrLabRecent;
}

function labDomainOf(v){
  for(const [k,ids] of Object.entries(LAB_CHAPTERS)) if(ids.includes(v)) return k;
  /* The suite overrides the visual-identity registry for GROUPING only; the palette
     registry is left untouched so nothing about how these laboratories look changes. */
  if(INVARIANCE_VIEWS.includes(v)) return 'invariance';
  if(LAB_SKETCHES.has(v)) return 'sketch';
  for(const [k,set] of Object.entries(PREMIUM_VIEW_DOMAINS)) if(set.has(v)) return k;
  return 'other';
}

function labNamesAllLangs(id){
  let out=String((S3_VIEW_NAMES&&S3_VIEW_NAMES[id])||'');
  try{ for(const L of Object.values(S3_VIEW_I18N)) if(L&&L[id]) out+=' '+L[id]; }catch(e){}
  return out;
}

const LAB_FEATURED=Object.freeze(['nsflow','nsgal','gmode','nbg','unify','triad','nsblow','vstretch','strobe','omnistrobe']);

const ORACLE={docs:null, idx:null, df:null, avgLen:0, extra:{formulas:false, problems:false, laws:false}, loading:null};

function oracleTokens(s){ return String(s||'').toLowerCase().replace(/\\([a-z]+)/g,' $1 ').normalize('NFKD').replace(/[̀-ͯ]/g,'').split(/[^0-9a-zа-яα-ω]+/).filter(w=>w.length>1&&w.length<40); }

function oracleAdd(D,doc){ doc.tokens=oracleTokens(doc.text); D.push(doc); }

function oracleDocsFrom(src){ const D=[];
  for(const L of (src.labs||[])) oracleAdd(D,{kind:'lab', id:L.id, title:L.title||L.id, status:L.status||'model', text:L.text||[L.title,L.id].join(' '), go:{lab:L.id}});
  for(const d of (src.discoveries||[])) oracleAdd(D,{kind:'discovery', id:d.id, title:d.en, status:d.kind, text:[d.en,d.ru,d.de,d.claim,(d.labs||[]).join(' '),d.domain].join(' '), go:{discovery:d.id}, labs:d.labs});
  for(const l of (src.leads||[])) oracleAdd(D,{kind:'lead', id:l.id, title:l.en, status:'open', text:[l.en,l.step,l.about].join(' '), go:{discovery:l.about}});
  for(const r of (src.relations||[])){ const a=r.a??r[0], b=r.b??r[1]; oracleAdd(D,{kind:'relation', id:a+'→'+b, title:`${a} ⟷ ${b} · ${r.label??r[3]}`, status:r.status??r[5], text:[a,b,r.type??r[2],r.label??r[3],r.claim??r[4]].join(' '), go:{lab:a}}); }
  for(const [id,c] of Object.entries(src.checks||{})) oracleAdd(D,{kind:'check', id, title:`${id} · ${c.what[0]}`, status:'checkable', text:[id,...c.what].join(' '), go:{formula:id}, check:id});
  return D; }

function oracleLabsFromDeclarations(decls){ return (decls||[]).map(d=>({id:d.id, title:d.title&&d.title.en||d.id, status:d.predictionClass||'model', text:[d.id,d.title&&d.title.en,d.title&&d.title.ru,d.title&&d.title.de,d.purpose,d.predictionTarget].join(' ')})); }

function oracleIndex(D){ const df=new Map(); let tot=0; D.forEach(d=>{ d.tf=new Map(); for(const t of d.tokens) d.tf.set(t,(d.tf.get(t)||0)+1); d.len=d.tokens.length; tot+=d.len; for(const t of d.tf.keys()) df.set(t,(df.get(t)||0)+1); });
  ORACLE.docs=D; ORACLE.df=df; ORACLE.vocab=[...df.keys()]; ORACLE.avgLen=tot/Math.max(1,D.length); return ORACLE; }

function oracleAsk(q,opt){ opt=opt||{}; if(!ORACLE.docs) oracleIndex((globalThis.__hccOracleSource||(()=>[]))()); const qt=oracleTokens(q), N=ORACLE.docs.length, k1=1.2, b=0.75, scores=new Map();
  for(const w of qt){ const terms=ORACLE.vocab.filter(t=>t===w||(w.length>=4&&t.startsWith(w))); for(const t of terms){ const n=ORACLE.df.get(t)||0, idf=Math.log(1+(N-n+0.5)/(n+0.5)), exact=t===w?1:0.8;
      for(const d of ORACLE.docs){ const f=d.tf.get(t); if(!f) continue; const s=exact*idf*f*(k1+1)/(f+k1*(1-b+b*d.len/ORACLE.avgLen)); scores.set(d,(scores.get(d)||0)+s); } } }
  const all=[...scores.entries()].map(([d,s])=>({d, s:s*(d.kind==='lab'||d.kind==='discovery'?1.15:1)})).sort((a,b)=>b.s-a.s), per=opt.perKind||6, byKind={};
  for(const {d,s} of all){ (byKind[d.kind]=byKind[d.kind]||[]); if(byKind[d.kind].length<per) byKind[d.kind].push({kind:d.kind, id:d.id, title:d.title, status:d.status, score:+s.toFixed(3), go:d.go}); }
  return {query:q, words:qt, indexed:N, complete:ORACLE.extra.formulas&&ORACLE.extra.problems&&ORACLE.extra.laws, total:all.length, top:all.slice(0,opt.limit||12).map(({d,s})=>({kind:d.kind, id:d.id, title:d.title, status:d.status, score:+s.toFixed(3), go:d.go})), byKind}; }

