function oracleStatusColour(s){ s=String(s||'').toLowerCase(); return /found|true|holds|verified|confirms|theorem|exact/.test(s)?'#7fe0a6':/revises|false|fails/.test(s)?'#ff8a7a':/open|conjecture|hypothesis/.test(s)?'#ffd27a':/law|checkable|tested/.test(s)?'#8fd0ff':'#b9c2d0'; }

