const OSC_QMAX=3e5, OSC_TAIL=6;

function oscContFrac(x,QMAX){
  QMAX=QMAX||OSC_QMAX;
  const terms=[], cv=[]; let v=x, pm1=1,pm2=0,qm1=0,qm2=1, stopped='budget';
  for(let k=0;k<80;k++){
    const t=Math.floor(v);
    const p=t*pm1+pm2, q=t*qm1+qm2;
    if(!Number.isFinite(q)||q>QMAX){ stopped='cap'; break; }
    terms.push(t); cv.push({p,q,d:q*Math.abs(q*x-p)});
    pm2=pm1; pm1=p; qm2=qm1; qm1=q;
    const r=v-t; if(r<=0){ stopped='terminated'; break; }
    v=1/r;
  }
  /* WHY THE EXPANSION STOPPED IS NOT A DETAIL, and not recording it was a real error
     for as long as this shipped. Stopping because the remainder went to zero means the
     number IS the fraction p/q. Stopping because the denominator passed the cap means
     nothing of the sort — it means the cap arrived first — and the two were reported
     identically as "rational". A ratio between two independently computed physical
     quantities is essentially never rational, and telling a reader that it is says the
     two phenomena return to phase exactly and forever, which is a claim about the world
     made by an arithmetic limit. */
  return {terms, convergents:cv, stopped};
}

function hccReachCompose(sens,tran){
  const legA=[];
  for(const ins of (sens&&sens.instruments)||[])
    for(const row of ins.rows||[])
      /* `moves` is what api/sensitivity.json calls it and `outputs` is what the page's
         own sensitivity.measure() calls it, and they are the same list under two names
         — with one real difference: the artifact keeps the six largest, so composing
         from a live measurement can find chains the file does not carry. Both are read
         here rather than renaming one, because renaming the published field would
         change a contract outside consumers already read. */
      for(const m of row.moves||row.outputs||[])
        if(m.slope!==null&&m.slope!==undefined)
          legA.push({input:`${ins.id}.${row.input}`, out:m.key, slope:m.slope,
            r2:(m.r2===null||m.r2===undefined)?null:m.r2,
            covered:(m.covered===null||m.covered===undefined)?(row.covered??null):m.covered});
  const legB=[];
  for(const r of (tran&&tran.routes)||[]){
    if(!r.from||!r.outputs) continue;
    for(const o of r.outputs){
      const s=(o.slope_from_source!==null&&o.slope_from_source!==undefined)
        ? o.slope_from_source : (r.hops===1?o.slope:null);
      if(s===null||s===undefined) continue;
      legB.push({from:r.from, out:o.key, slope:s, hops:r.hops, route:r.name,
        r2:(o.r2_from_source!==null&&o.r2_from_source!==undefined)?o.r2_from_source:o.r2,
        drift:o.drift, live:r.live, stable:o.stable||null});
    }
  }
  /* ── AND A PRODUCT OF TWO NUMBERS IS NOT A LAW BECAUSE BOTH NUMBERS EXIST ──
     This composed every non-null slope and published the product as an exponent —
     including for legs the atlas's OWN measurement says are not power laws. The worst
     of them: ns.central_density → wd.radius_km came out as a clean-looking -0.4783,
     while the white-dwarf leg it multiplies has R² 0.84 and a local slope running from
     -0.36 at the low end to -5.05 at the high one. That is the Chandrasekhar breakdown,
     which this atlas LOCATED and then quietly averaged away into a scaling law that
     does not exist. A reader was handed a number with no way to know it describes
     nothing.

     The chain is not dropped, because dropping it would hide the finding — the same
     reason ns.step stays in this file. It carries a verdict instead, derived from
     numbers that were already measured:

       A LEG IS A POWER LAW ACROSS ITS RANGE WHEN ITS EXPONENT DOES NOT CHANGE BY AS
       MUCH AS THE EXPONENT ITSELF, AND ITS SINGLE-LINE FIT IS GOOD.

     |drift| <= |slope| is the first half and it is the sharper instrument, because R²
     stays high for a gently curved fit over a narrow range. The cut is not tuned: over
     the forty-four chains this atlas currently composes, relative drift takes the
     values 0.000, 0.082, 0.087, 0.160, 0.161 — and then 2.753, 4.524, 6.671, 11.513.
     Any threshold in that seventeen-fold gap gives the same partition; one is chosen
     because it MEANS something rather than because it fits this data.

     Both legs are judged, which is why sensitivity now publishes the near leg's R²: a
     product with one half checked and the whole presented as checked is the silence
     this is being written to end. A leg whose fit quality was never recorded is
     'unjudged' and says so — not 'true', which is what a missing number defaults to
     when nobody thinks about it. */
  const DRIFT_LIMIT=1, R2_FLOOR=0.99;
  const verdict=(slope,r2,drift)=>{
    if(drift===null||drift===undefined) return {ok:null, why:'the far leg has too few live samples for the low-third and high-third fits that decide whether its exponent is constant, so this chain is UNJUDGED rather than false — sweep the route at more samples and it becomes decidable'};
    const rel=Math.abs(drift)/Math.max(0.05,Math.abs(slope));
    if(rel>DRIFT_LIMIT) return {ok:false, why:`the exponent drifts by ${drift.toFixed(3)} across the sweep against a fitted ${slope.toFixed(3)} — it is one thing at the low end and another at the high one, so a single exponent describes neither`, drifts:true};
    if(r2===null||r2===undefined) return {ok:null, why:'the exponent is constant across the sweep, but the quality of the single-line fit was not recorded'};
    if(r2<R2_FLOOR) return {ok:false, why:`the local exponent holds but the single line fits at R² ${r2.toFixed(4)}, below ${R2_FLOOR}`};
    return {ok:true, why:`the exponent is constant to ${Math.abs(drift).toFixed(3)} across the sweep and the line fits at R² ${r2.toFixed(4)}`};
  };
  /* ── AND WHERE IT DOES HOLD, WHICH "NOT A POWER LAW" NEVER SAID ────────────
     A white dwarf's radius goes as M^-0.36 at low mass and M^-5.05 near the
     Chandrasekhar limit, and this file used to answer "not a power law" and stop. The
     exponent is not missing; it is TWO exponents, and the interesting number is where
     the first one stops. The transfer measurement now searches for the widest window
     over which the local exponent does not change by more than the exponent itself —
     the same rule this verdict uses, deliberately, so a leg cannot be a law by one
     standard and not by another — and a chain that fails carries the window it would
     have passed on, in the delivered quantity's own units rather than in the decades
     the fit was taken in. */
  const windowed=(b,a)=>{ const w=b.stable; if(!w||w.whole) return null;
    return {from:w.from, to:w.to, decades:w.decades,
      exponent:a.slope*w.slope, far_slope:w.slope,
      r2:w.r2, samples:w.n, of:w.of}; };
  const chains=[];
  for(const a of legA) for(const b of legB) if(a.out===b.from){
    const vb=verdict(b.slope,b.r2,b.drift);
    /* the near leg carries no drift measurement, so it is judged on its fit alone */
    /* a slope fitted over a prefix of a declared domain is the exponent THERE, and
       multiplying it into a chain claims it everywhere. Such a leg is not judged true. */
    const cov=(a.covered===null||a.covered===undefined)?1:a.covered;
    const va=(cov<0.999) ? {ok:null, why:`the near leg was swept only ${(cov*100).toFixed(1)}% of the way along its declared drive before the budget stopped it, so its exponent is the one it has THERE and nothing is known about the rest`}
      : (a.r2===null||a.r2===undefined) ? {ok:null, why:'the near leg\u2019s fit quality was not recorded'}
      : (a.r2>=R2_FLOOR ? {ok:true, why:`the near leg fits at R² ${a.r2.toFixed(4)}`}
                        : {ok:false, why:`the near leg fits at only R² ${a.r2.toFixed(4)}`});
    const ok=(va.ok===false||vb.ok===false) ? false : ((va.ok===true&&vb.ok===true) ? true : null);
    chains.push({
      control:a.input, through:a.out, reaches:b.out, route:b.route,
      exponent:a.slope*b.slope, leg_control_to_output:a.slope, leg_output_to_far:b.slope,
      laboratories:1+b.hops, near_r2:(a.r2===null||a.r2===undefined)?null:a.r2,
      near_covered:cov,
      far_r2:b.r2, far_drift:b.drift, far_live:b.live,
      /* ── AND AN UNJUDGED CHAIN MUST NAME THE LEG IT COULD NOT JUDGE ────────
         This reported the leg that PASSED. A three-laboratory chain measured live at
         sixty-four samples came back "the near leg fits at R² 1.0000" and nothing else,
         with power_law null — so the one field a reader would look at to find out what
         is missing told them about the half that was fine. The far leg was the unjudged
         one: at sixty-four samples that route delivers four live points, and the low-
         third and high-third fits that decide whether the exponent is constant need
         more than that. The build densifies to three hundred and eighty-four and can
         judge it; the page at sixty-four cannot, and now says which. */
      power_law:ok, holds_on:(ok===false&&vb.drifts)?windowed(b,a):null,
      why: ok===true ? `${va.why}; ${vb.why}`
         : ok===false ? ((vb.ok===false?vb.why:va.why)
             + ((vb.drifts&&windowed(b,a)) ? ` — it DOES hold where the coupling delivers ${windowed(b,a).from.toPrecision(4)} to ${windowed(b,a).to.toPrecision(4)}, ${windowed(b,a).decades.toFixed(2)} decades on ${windowed(b,a).samples} of ${windowed(b,a).of} live samples, with a composed exponent of ${windowed(b,a).exponent.toFixed(4)}` : ''))
         : (vb.ok===null?vb.why:va.why)});
  }
  chains.sort((x,y)=>Math.abs(y.exponent)-Math.abs(x.exponent)||x.control.localeCompare(y.control));
  return chains;
}

const AGORA_SPECS=Object.freeze({
  scene:{doc:'Where the atlas stands: world, laboratory, selected object, scale layer, epoch (days from J2000 and date), clock rate and paused, laboratory clock factor, camera distance and its unit, the agents on stage.', args:{}},
  find:{doc:'Search every selectable object of every world by name (Sun, planets, moons, stars, galaxies, structures, laboratory objects). Returns keys for focus, measure, mark.', args:{q:{type:'string',description:'name or fragment'}, n:{type:'number',description:'maximum results, default 12'}}, required:['q']},
  worlds:{doc:'The worlds and the laboratories that can be entered, with their ids.', args:{}},
  go:{doc:'Enter a world, and optionally a laboratory in it. The reader sees the transition.', args:{world:{type:'string'}, lab:{type:'string'}}, required:['world'], moves:true},
  layer:{doc:'The Solar world scale layer: local, galactic, andromeda or cosmic.', args:{layer:{type:'string',enum:['local','galactic','andromeda','cosmic']}}, required:['layer'], moves:true},
  focus:{doc:'Select an object by key (from find) and fly the camera to it; the agent\'s presence flies with it and a beam marks it.', args:{key:{type:'string'}}, required:['key'], moves:true},
  camera:{doc:'Orbit the camera about its target, paced, never a cut: distance in scene units (AU in the Solar world, Gly in the Observable), azimuth and elevation in degrees, over a number of seconds.', args:{distance:{type:'number'}, azimuth:{type:'number'}, elevation:{type:'number'}, seconds:{type:'number'}}, moves:true},
  time:{doc:'Set the one clock: epochDays from J2000 or an ISO date, rate in days per second (negative runs backward), paused. Every laboratory follows its rate.', args:{epochDays:{type:'number'}, date:{type:'string'}, rate:{type:'number'}, paused:{type:'boolean'}}},
  instruments:{doc:'The typed instruments — every model the atlas can evaluate — filtered by a query on id, title, world or laboratory.', args:{q:{type:'string'}}},
  describe:{doc:'Inputs, outputs, units and domains of one instrument.', args:{id:{type:'string'}}, required:['id']},
  run:{doc:'Evaluate an instrument with inputs: numbers with units and provenance, from the atlas\'s own deterministic models.', args:{id:{type:'string'}, input:{type:'object'}}, required:['id']},
  kernels:{doc:'The pure computational kernels that reproducibility tracks may call.', args:{}},
  kernel:{doc:'Run one kernel with JSON arguments, exactly as a reproducibility track would.', args:{op:{type:'string'}, args:{type:'object'}}, required:['op']},
  bus:{doc:'Live readings published by the open world or laboratory: value, unit and age, optionally filtered by a key prefix.', args:{prefix:{type:'string'}}},
  measure:{doc:'An object at the current epoch: its scene position and its distances from the Sun, the Earth and the camera (scene units), with its card rows.', args:{key:{type:'string'}}, required:['key']},
  phase:{doc:'Open the phase portrait of the open laboratory — two bus keys against each other, or one against itself lagged (a Takens delay embedding) — and read its correlation dimension.', args:{x:{type:'string'}, y:{type:'string'}, lag:{type:'number'}}},
  oracle:{doc:'Ask the atlas\'s own index one question across every kind of knowledge it holds.', args:{q:{type:'string'}}, required:['q']},
  say:{doc:'Speak to the reader: a caption in the agent\'s colour, shown on the page and in the headset.', args:{text:{type:'string'}}, required:['text']},
  mark:{doc:'Pin a note in the scene, on an object (key) or at a point (xyz in scene units). It stays, and follows the object.', args:{text:{type:'string'}, key:{type:'string'}, xyz:{type:'array',items:{type:'number'}}}, required:['text']},
  predict:{doc:'Make a checkable prediction: a claim, an epoch (epochDays or ISO date), optionally an object key to pin it on, and a check {cmd, args, path, expect, tol}. When the clock reaches the epoch it stops there, runs the check in front of everyone and marks the claim confirmed or refuted; with no epoch it is checked now.', args:{claim:{type:'string'}, epochDays:{type:'number'}, date:{type:'string'}, key:{type:'string'}, check:{type:'object',description:'{cmd, args, path, expect, tol}: a command of this vocabulary, the dotted path to a number in its result, the value expected and the tolerance'}}, required:['claim','check']},
  highlight:{doc:'Ring objects by key so the reader sees what the agent is talking about.', args:{keys:{type:'array',items:{type:'string'}}}, required:['keys']},
  clear:{doc:'Remove this agent\'s marks, rings and pending predictions.', args:{}},
  tour:{doc:'A choreographed sequence: steps of {cmd, args, dwell seconds}, run in order in front of the reader. Returns every step\'s result.', args:{steps:{type:'array',items:{type:'object'}}}, required:['steps']},
  look:{doc:'SEE what the reader sees: a fresh frame of the scene as an image (JPEG, the given width, default 768 px), with the caption line, the world and the epoch. MCP hosts receive it as an image.', args:{width:{type:'number'}}},
  read:{doc:'READ every window the reader has open — panels, cards, the caption, the laboratory bar, the time machine — as text, or one panel by id.', args:{panel:{type:'string'}}},
  panels:{doc:'Every window and tool of the atlas (panel ids, whether open, whether available in this world) and every button that opens one.', args:{}},
  panel:{doc:'Open, close or toggle any window of the atlas by id (from panels), in front of the reader.', args:{id:{type:'string'}, open:{type:'boolean'}}, required:['id']},
  press:{doc:'Press any control of the atlas the reader could press — a button, chip, tab, checkbox — found by its visible label, aria-label, title or #id. The control glows in the agent\'s colour before it is pressed. The Agora\'s own consent controls are out of reach.', args:{label:{type:'string'}, nth:{type:'number',description:'which match, from 0, when several share the label'}}, required:['label']},
  input:{doc:'Set any slider, number, text field or select of the atlas — found by its label, aria-label, placeholder or #id — and fire its change, in front of the reader.', args:{label:{type:'string'}, value:{type:'string'}}, required:['label','value']},
  controls:{doc:'Every control the reader can operate right now — buttons, chips, checkboxes, sliders, selects — with labels and current values, filtered by a query.', args:{q:{type:'string'}}},
  point:{doc:'GUIDE the reader: a glowing frame and a note in the agent\'s colour on a control or window (label or #id), or on an object in the scene (key), for some seconds.', args:{text:{type:'string'}, label:{type:'string'}, key:{type:'string'}, seconds:{type:'number'}}, required:['text']},
  guide:{doc:'A guided walk for the reader: steps of {text, label | key, wait: "click" | seconds}. Each step points; a click step waits for the reader to press the thing pointed at (up to 90 s). Returns what the reader did.', args:{steps:{type:'array',items:{type:'object'}}}, required:['steps']},
  ask:{doc:'ASK the reader a question on the stage, with options to choose from (or a free answer when none are given); returns the answer, or that none came in the time allowed (default 60 s).', args:{question:{type:'string'}, options:{type:'array',items:{type:'string'}}, seconds:{type:'number'}}, required:['question']},
  note:{doc:'WRITE to the shared journal: a record that keeps the place it was written — world, laboratory, epoch, camera, selection — so anyone, reader or agent, can return to it. Pinned in the scene where it was written.', args:{title:{type:'string'}, text:{type:'string'}, tags:{type:'array',items:{type:'string'}}}, required:['text']},
  journal:{doc:'READ the shared journal: every record left by readers and agents, newest first, filtered by a query on title, text, tags or author.', args:{q:{type:'string'}, n:{type:'number'}}},
  visit:{doc:'Take the reader to the place a journal record keeps — the world, the laboratory, the epoch, the camera and the selection it was written in.', args:{id:{type:'string'}}, required:['id'], moves:true}
});

function agoraTools(){ return Object.entries(AGORA_SPECS).map(([k,s])=>({name:'atlas_'+k, description:s.doc,
  inputSchema:{type:'object', properties:Object.fromEntries(Object.entries(s.args||{}).map(([a,t])=>[a,{...t}])), required:[...(s.required||[])]}})); }

function agoraJson(v,depth=0){ if(v==null) return v===undefined?null:v;
  if(typeof v==='number') return Number.isFinite(v)?v:String(v);
  if(typeof v==='string') return v.length>4000?v.slice(0,4000)+'…':v;
  if(typeof v==='boolean') return v;
  if(typeof v==='function'||typeof v==='symbol') return undefined;
  if(depth>7) return '[…]';
  if(v.isVector3) return [v.x,v.y,v.z];
  if(Array.isArray(v)||ArrayBuffer.isView(v)){ const a=Array.from(v).slice(0,240).map(x=>agoraJson(x,depth+1)); return a; }
  if(typeof v==='object'){ const o={}; let n=0; for(const k of Object.keys(v)){ if(n++>160) break; const x=agoraJson(v[k],depth+1); if(x!==undefined) o[k]=x; } return o; }
  return String(v); }

function agoraCheckArgs(cmd,a){ const s=AGORA_SPECS[cmd]; if(!s) throw new Error('unknown command: '+cmd+' — the vocabulary is '+Object.keys(AGORA_SPECS).join(', '));
  a=a&&typeof a==='object'&&!Array.isArray(a)?a:{};
  for(const r of s.required||[]) if(a[r]==null) throw new Error(cmd+': missing '+r);
  for(const [k,v] of Object.entries(a)){ const t=(s.args||{})[k]; if(!t) throw new Error(cmd+': unknown argument '+k); if(v==null) continue;
    const ok=t.type==='number'?Number.isFinite(v):t.type==='string'?typeof v==='string':t.type==='boolean'?typeof v==='boolean':t.type==='array'?Array.isArray(v):t.type==='object'?(typeof v==='object'&&!Array.isArray(v)):true;
    if(!ok) throw new Error(cmd+': '+k+' must be '+t.type); if(t.enum&&!t.enum.includes(v)) throw new Error(cmd+': '+k+' must be one of '+t.enum.join(', ')); }
  return a; }

function agoraPath(o,path){ let x=o; for(const p of String(path||'').split('.').filter(Boolean)){ if(x==null) return undefined; x=x[Array.isArray(x)?+p:p]; } return x; }

function agoraNum(x){ if(typeof x==='number') return x; if(typeof x==='string'){ const m=x.replace(/[−–]/g,'-').match(/-?\d+(\.\d+)?(e[+-]?\d+)?/i); return m?+m[0]:NaN; } if(x&&typeof x==='object'&&'value' in x) return agoraNum(x.value); return NaN; }

function agoraEpochOf(a){ if(Number.isFinite(a.epochDays)) return a.epochDays; if(typeof a.date==='string'){ const t=Date.parse(a.date); if(Number.isFinite(t)) return (t-Date.UTC(2000,0,1,12))/864e5;
    const y=Number(a.date); if(Number.isFinite(y)) return (y-2000)*365.2425; throw new Error('unreadable date: '+a.date); } return null; }

